(window.TRENER_PACKS=window.TRENER_PACKS||{})["ionnyy-obmen-gidroliz"]={"id": "ionnyy-obmen-gidroliz", "subject": "Химия", "title": "Электролиты, РИО (№ 6, 30) и гидролиз/pH (№ 21) ЕГЭ-2027 с нуля до 100 баллов", "version": "26.11.2026", "konspekt": "ionnyy-obmen-gidroliz", "codes": ["1.9", "1.10"], "kod": {"p": [{"id": "p1", "t": "Электролитическая диссоциация, степень α и сильные/слабые электролиты", "x": "Вещества с ионной или сильно полярной ковалентной связью в воде распадаются на гидратированные ионы (диполи H2O ориентируются к катиону кислородом δ−, к аниону водородом δ+). Степень диссоциации α = N_дисс / N_общ у слабых электролитов растёт при разбавлении и нагревании. Все растворимые соли («Р») — сильные электролиты, а сильных кислот для ЕГЭ ровно 9.", "ref": "01.1"}, {"id": "p2", "t": "Таблица растворимости ФИПИ, позиционное правило и 5 правил ПИУ/СИУ", "x": "В полном ионном уравнении (ПИУ) расписываются только 9 сильных кислот, щёлочи и растворимые соли («Р»); слабые кислоты, осадки («Н» и «М»), газы, вода и NH3·H2O пишутся молекулами. Исключение — малорастворимые щёлочи Ca(OH)2 и Sr(OH)2 («М»): слева (раствор) расписываются, справа (осадок) — нет. В СИУ сокращаются ионы-наблюдатели и общие множители.", "ref": "02.1"}, {"id": "p3", "t": "Условия необратимости РИО, растворение осадков и комплексы", "x": "РИО протекает до конца без изменения степеней окисления при образовании осадка («Н»/«М»), газа (CO2, SO2, H2S, NH3) или слабого электролита (H2O, NH3·H2O, HNO2, CH3COOH, HF, H3PO4, H2SiO3↓). В РИО двух солей обе исходные соли обязаны иметь пометку «Р». Амфотерные гидроксиды растворяются и в сильных кислотах, и в щелочах с образованием гидроксокомплексов.", "ref": "03.1"}, {"id": "p4", "t": "Кислые соли в РИО: избыток/недостаток и дилемма HSO4⁻", "x": "Растворимые кислые соли слабых кислот распадаются на катион металла и целый кислый анион (HCO3⁻, HSO3⁻, HS⁻, H2PO4⁻, HPO4²⁻ на H⁺ в ПИУ не расписываются). Для HSO4⁻ ФИПИ допускает оба варианта записи, но строго согласованно слева и справа. При реакции Ba(OH)2 с NaHCO3 соотношение 1:1 даёт BaCO3↓ + NaOH + H2O, а 1:2 — BaCO3↓ + Na2CO3 + 2H2O.", "ref": "04.1"}, {"id": "p5", "t": "Совместный гидролиз, граница РИО/ОВР и критерии № 30", "x": "Соли Al³⁺, Cr³⁺ (с CO3²⁻/HCO3⁻/S²⁻/HS⁻/SO3²⁻/HSO3⁻) и Fe³⁺ (только с CO3²⁻/HCO3⁻) вступают в совместный гидролиз (РИО: осадок гидроксида + газ). Пары Fe³⁺ с S²⁻/SO3²⁻/I⁻ и Cu²⁺ с I⁻ — скрытые ОВР, запрещённые в № 30, как и оксиды, простые вещества и твёрдые соли с H2SO4(конц.). Переход CrO4²⁻ ⇄ Cr2O7²⁻ — полноценная РИО.", "ref": "05.1"}, {"id": "p6", "t": "Две пробирки X и Y и качественные признаки РИО в № 6", "x": "В задании № 6 нужно перевести наблюдаемые признаки в двух пробирках (цвет и растворимость осадка, запах газа, отсутствие видимых признаков) в конкретные реагенты X и Y из списка 5 веществ. Порядок цифр X и Y строго фиксирован: перестановка обнуляет оба балла.", "ref": "06.1"}, {"id": "p7", "t": "Гидролиз 4 типов солей, 1-я ступень и смещение равновесия", "x": "Гидролиз всегда идёт по слабому иону, а среду раствора определяет сильный ион: по катиону — кислая (pH < 7), по аниону — щелочная (pH > 7), сильное + сильная — гидролиза нет (pH = 7). Обратимый гидролиз многозарядных ионов идёт по 1-й ступени, усиливается при нагревании и разбавлении водой; нерастворимые соли в воде не гидролизуются.", "ref": "07.1"}, {"id": "p8", "t": "Ионное произведение воды Kw, шкала pH, индикаторы и 6 кислых солей", "x": "При 25 °C Kw = [H⁺]·[OH⁻] = 10⁻¹⁴, pH = −lg[H⁺]: чем больше [H⁺], тем меньше pH. Из 6 кислых солей щелочных металлов три дают кислую среду (NaHSO4 — сильнокислая, NaH2PO4 и NaHSO3 — слабокислая) и три — слабощелочную (NaHCO3, Na2HPO4, NaHS). При равной молярной концентрации pH(H2SO4) < pH(HCl) и pH(NaOH) < pH(Ba(OH)2).", "ref": "08.1"}, {"id": "p9", "t": "Ранжирование неорганических и органических растворов в № 21", "x": "В № 21 припиши каждому из 4 веществ этаж на шкале pH, разведи соседей внутри одного этажа и дважды проверь направление (возрастание pH — от кислого к щелочному, убывание — от щелочного к кислому). Среди органики: карбоновые кислоты и фенол — pH < 7; спирты, глюкоза, глицин, анилин — pH ≈ 7; амины, ацетаты, феноляты, алкоголяты — pH > 7; соли аминов — pH < 7.", "ref": "09.1"}], "z": [{"id": "z1", "x": "9 сильных кислот для ЕГЭ: HCl, HBr, HI, HNO3, H2SO4, HClO4, HClO3, HMnO4, H2Cr2O7. Кислоты HF, H3PO4, HNO2, H2SO3, H2CO3, H2S, H2SiO3, CH3COOH в ПИУ на ионы НЕ расписываются.", "sk": "electrolytes", "ref": "01.21"}, {"id": "z2", "x": "Стандарт оформления № 30: заряд иона пишется цифрой перед знаком (Fe^{2+}, SO4^{2−}), формула NH4OH запрещена (пишем NH3·H2O без газа или NH3↑ + H2O с газом), коэффициенты в СИУ всегда сокращаются.", "sk": "fipi_solubility_piu", "ref": "02.17"}, {"id": "z3", "x": "Позиционное правило: малорастворимые щёлочи Ca(OH)2 и Sr(OH)2 («М») слева (раствор) расписываются на ионы, а справа (осадок) пишутся молекулой. Малорастворимые соли («М»: CaSO4, Ag2SO4, PbCl2, LiF) не расписываются нигде.", "sk": "fipi_solubility_piu", "ref": "02.12"}, {"id": "z4", "x": "Условности таблицы ФИПИ-2027: у Ca(CH3COO)2, Ba/Mg/Sr(HCO3)2 и (NH4)3PO4 стоит прочерк «–» (не выбирай их слева в № 30); Li3PO4 и Li2SiO3 — осадки («Н»), а Li2CO3, AgF и CaCrO4 — «Р».", "sk": "fipi_solubility_piu", "ref": "02.9"}, {"id": "z5", "x": "Гидроксиды AgOH и Hg(OH)2 не существуют («–» в таблице ФИПИ): в реакции с щёлочью образуются Ag2O↓ + H2O и HgO↓ + H2O.", "sk": "rio_conditions", "ref": "03.33"}, {"id": "z6", "x": "Гидроксокомплексы [Al(OH)4]^{−} и [Zn(OH)4]^{2−} в ПИУ расписываются на катион металла и целый комплексный анион (квадратные скобки не разбиваются). В избытке NH3·H2O осадок Al(OH)3 не растворяется.", "sk": "rio_conditions", "ref": "03.24"}, {"id": "z7", "x": "Фосфит натрия Na2HPO3 и гипофосфит NaH2PO2 — псевдокислые СРЕДНИЕ соли (H3PO3 двухосновна, H3PO2 одноосновна): в № 30 они не нейтрализуются щёлочью, а в № 21 гидролизуются по аниону (pH > 7).", "sk": "acid_salts_rio", "ref": "04.31"}, {"id": "z8", "x": "Совместный гидролиз Al^{3+}/Cr^{3+} (с CO3^{2−}, S^{2−}, SO3^{2−} и кислыми) и Fe^{3+} (с CO3^{2−}/HCO3^{−}) — это РИО (№ 30), а Fe^{3+} с S^{2−}/SO3^{2−}/I^{−} и Cu^{2+} с I^{−} — ОВР (запрещены в № 30).", "sk": "joint_hydrolysis_30", "ref": "05.10"}, {"id": "z9", "x": "Переход дихромат ↔ хромат (K2Cr2O7 + 2KOH → 2K2CrO4 + H2O и 2K2CrO4 + H2SO4 → K2Cr2O7 + K2SO4 + H2O) — это РИО (везде Cr^{+6}), с признаком «изменение окраски раствора без осадка и газа».", "sk": "joint_hydrolysis_30", "ref": "05.14"}, {"id": "z10", "x": "Осадок BaCO3 нельзя растворить в H2SO4 (выпадет новый осадок BaSO4↓) — для растворения BaCO3 в № 6 выбирай HCl или HNO3. BaSO3 в HCl растворяется (SO2↑), а BaSO4 — нет.", "sk": "kim6_tubes", "ref": "06.18"}, {"id": "z11", "x": "Ловушка магния Mg^{2+}: в отличие от Ca^{2+}, Sr^{2+}, Ba^{2+}, гидроксид Mg(OH)2 — слабое нерастворимое основание, поэтому MgCl2, MgSO4, Mg(NO3)2 гидролизуются по катиону (кислая среда, pH < 7).", "sk": "hydrolysis_4types", "ref": "07.18"}, {"id": "z12", "x": "Ацетат аммония CH3COONH4 гидролизуется обратимо по обоим ионам, но среда нейтральная (pH ≈ 7), так как K_a(CH3COOH) ≈ K_b(NH3·H2O). Нерастворимые соли (CaCO3, BaSO4, CuS) в воде не гидролизуются.", "sk": "hydrolysis_4types", "ref": "07.14"}, {"id": "z13", "x": "Шестёрка кислых солей в № 21: кислая среда — NaHSO4 (сильнокислая), NaH2PO4 и NaHSO3 (слабокислая); щелочная среда — NaHCO3, Na2HPO4 и NaHS (слабощелочная).", "sk": "ph_scale_acid_salts", "ref": "08.16"}, {"id": "z14", "x": "В органике для № 21: анилин C6H5NH2 и глицин NH2CH2COOH дают почти нейтральную среду (pH ≈ 7); алкоголят C2H5ONa гидролизуется необратимо до NaOH (сильнощелочная среда).", "sk": "kim21_ranking", "ref": "09.4"}]}, "skills": [{"id": "electrolytes", "name": "Электролиты, степень диссоциации α и 9 сильных кислот", "ref": "01", "idea": "Безошибочно отличать электролиты от неэлектролитов, сильные электролиты от слабых и предсказывать изменение степени диссоциации α.", "pre": {"type": "one", "q": "Какое из перечисленных веществ в разбавленном водном растворе является СИЛЬНЫМ электролитом?", "o": ["CH3COONa", "H3PO4", "HF", "C2H5OH"], "a": 0, "ex": "Ацетат натрия CH3COONa — растворимая соль («Р» в таблице ФИПИ) с ионной связью между Na^{+} и CH3COO^{−}, поэтому это сильный электролит (α ≈ 100%).", "d": {"1": "Фосфорная кислота H3PO4 — электролит средней силы, в ПИУ на ионы не расписывается.", "2": "Плавиковая кислота HF — слабый/средний электролит, не входит в 9 сильных кислот ЕГЭ.", "3": "Этанол C2H5OH — неэлектролит (в воде на ионы не распадается)."}}, "pair": {"type": "one", "cases": [["Уксусная кислота CH3COOH (р-р)", "Ковалентная полярная связь O—H, α ≈ 1%"], ["Ацетат натрия CH3COONa (р-р)", "Ионная связь между Na^{+} и CH3COO^{−}, статус «Р»"]], "q": "Как эти два вещества записываются в полном ионном уравнении (ПИУ) задания № 30?", "o": ["CH3COOH — молекулой, CH3COONa — в виде ионов Na^{+} + CH3COO^{−}", "Оба вещества пишутся молекулами, так как уксусная кислота слабая", "Оба вещества расписываются на ионы, так как оба растворимы в воде", "CH3COOH расписывается на ионы, а CH3COONa пишется молекулой"], "a": 0, "ex": "Все растворимые в воде соли («Р») — сильные электролиты независимо от силы образующей их кислоты, а слабые кислоты в ПИУ всегда остаются молекулами."}, "fade": {"q": "Определи поведение слабого электролита CH3COOH в воде и влияние факторов на α:", "steps": ["В кристалле NaCl связь ионная, а диполи воды поворачиваются к Na^{+} атомом {кислорода (δ−)|водорода (δ+)|хлора}.", "Уксусная кислота CH3COOH диссоциирует обратимо; при разбавлении раствора водой степень диссоциации α {увеличивается|уменьшается|не меняется}.", "Многоосновная слабая кислота H3PO4 диссоциирует ступенчато, причём легче всего идёт {первая|вторая|третья} ступень."]}, "bug": {"q": "Найди ошибочное утверждение о диссоциации и электролитах:", "steps": ["В список 9 сильных кислот ЕГЭ входят HCl, HBr, HI, HNO3, H2SO4, HClO4, HClO3, HMnO4, H2Cr2O7.", "Оксиды (CO2, SO3, Fe2O3), простые вещества (Fe, O2) и глюкоза (C6H12O6) относятся к неэлектролитам.", "Азотистая кислота HNO2 и фтороводородная кислота HF являются сильными электролитами, поэтому в ПИУ их расписывают на ионы.", "Твёрдый кристаллический NaCl не проводит электрический ток, так как его ионы жёстко закреплены в кристаллической решётке."], "bad": 2, "fix": "HNO2 и HF — слабые/средние кислоты (не входят в 9 сильных кислот ЕГЭ), поэтому в ПИУ и СИУ они записываются в молекулярной форме.", "why": "Расписывание HNO2, HF, H3PO4 или H2SO3 на ионы в задании № 30 автоматически обнуляет второй балл за ионные уравнения."}, "recall": {"q": "Назови по памяти 9 сильных кислот ЕГЭ и 4 фактора, влияющих на степень диссоциации α.", "points": ["9 сильных кислот: HCl, HBr, HI, HNO3, H2SO4, HClO4, HClO3, HMnO4, H2Cr2O7.", "Факторы α: природа электролита, природа растворителя, разбавление водой (для слабых α растёт), температура (обычно α растёт при нагревании).", "Все растворимые соли («Р») — сильные электролиты, даже соли слабых кислот и слабых оснований."]}}, {"id": "fipi_solubility_piu", "name": "Таблица растворимости ФИПИ и 5 правил ПИУ/СИУ", "ref": "02", "idea": "Читать официальную таблицу ФИПИ-2027 с её условностями, применять позиционное правило Ca(OH)2/Sr(OH)2 и безупречно оформлять ПИУ и СИУ.", "pre": {"type": "one", "q": "Какая запись сокращённого ионного уравнения (СИУ) соответствует строгим критериям оформления ФИПИ ЕГЭ-2027?", "o": ["Fe^{3+} + 3OH^{−} → Fe(OH)3↓", "Fe^{+3} + 3OH^{−1} → Fe(OH)3↓", "2H^{+} + 2OH^{−} → 2H2O", "NH4^{+} + OH^{−} → NH4OH"], "a": 0, "ex": "Заряд иона пишется цифрой перед знаком (Fe^{3+}), единица не ставится (OH^{−}), коэффициенты сокращены до минимальных целых.", "d": {"1": "Fe^{+3} и OH^{−1} — формат степени окисления, а не заряда иона; за это снимают балл в № 30.", "2": "Коэффициенты в СИУ не сокращены на 2 (должно быть H^{+} + OH^{−} → H2O).", "3": "Формула NH4OH запрещена на ЕГЭ: нужно писать NH3·H2O (без газа) или NH3↑ + H2O (при нагревании)."}}, "pair": {"type": "one", "cases": [["Ca(OH)2 + 2HCl → CaCl2 + 2H2O", "Известковая вода Ca(OH)2 («М») стоит СЛЕВА в реагентах"], ["CaCl2 + 2NaOH → Ca(OH)2↓ + 2NaCl", "Гидроксид кальция Ca(OH)2 («М») выпадает СПРАВА в продуктах"]], "q": "Как правильно записать Ca(OH)2 в ПИУ первого и второго уравнения соответственно?", "o": ["В первом — ионами Ca^{2+} + 2OH^{−}, во втором — молекулой Ca(OH)2↓", "В обоих уравнениях молекулой Ca(OH)2, так как в таблице стоит «М»", "В обоих уравнениях ионами Ca^{2+} + 2OH^{−}, так как это сильная щёлочь", "В первом — молекулой Ca(OH)2, во втором — ионами Ca^{2+} + 2OH^{−}"], "a": 0, "ex": "По позиционному правилу ФИПИ малорастворимые щёлочи Ca(OH)2 и Sr(OH)2 слева (в растворе) расписываются на ионы, а справа (в осадке) пишутся молекулой."}, "fade": {"q": "Заполни правила работы с официальной таблицей ФИПИ-2027:", "steps": ["Малорастворимая соль CaSO4 («М») в ПИУ {не расписывается ни слева, ни справа|расписывается слева, как Ca(OH)2|расписывается везде}.", "Среди солей лития в таблице ФИПИ осадок («Н») образуют {Li3PO4 и Li2SiO3|Li2CO3 и LiNO3|LiCl и Li2SO4}.", "В официальной таблице ФИПИ-2027 прочерк «–» стоит у {Ca(CH3COO)2 и Ba(HCO3)2|AgF и CaCrO4|Ca(HCO3)2 и (NH4)2HPO4}, поэтому слева в № 30 их не выбирают."]}, "bug": {"q": "Найди ошибку в рассуждении при составлении ПИУ и СИУ для реакции Na2SO4 + BaCl2 → BaSO4↓ + 2NaCl:", "steps": ["Обе исходные соли Na2SO4 и BaCl2 имеют пометку «Р» в таблице ФИПИ, поэтому РИО двух солей возможна.", "Продукт BaSO4 имеет пометку «Н» — это белый осадок, он пишется молекулой.", "Записываем ПИУ: Na2^{+} + SO4^{2−} + Ba^{2+} + Cl2^{−} → BaSO4↓ + 2Na^{+} + 2Cl^{−}.", "Сокращаем ионы-наблюдатели Na^{+} и Cl^{−} и получаем СИУ: Ba^{2+} + SO4^{2−} → BaSO4↓."], "bad": 2, "fix": "В ПИУ число ионов выносится вперёд как коэффициент: 2Na^{+} + SO4^{2−} + Ba^{2+} + 2Cl^{−} → BaSO4↓ + 2Na^{+} + 2Cl^{−}. Ионов Na2^{+} и Cl2^{−} не существует.", "why": "Путаница между нижним индексом внутри формулы и коэффициентом перед свободным ионом — частая причина потери 2-го балла в № 30."}, "recall": {"q": "Назови 5 строгих правил оформления ПИУ и СИУ на 2/2 балла в № 30.", "points": ["Заряд иона — цифрой вперёд (Fe^{2+}, SO4^{2−}), без знака спереди.", "Никакого NH4OH — только NH3·H2O или NH3↑ + H2O.", "В СИУ обязательно сокращать общие множители и убирать все ионы-наблюдатели.", "Соблюдать баланс и по атомам, и по суммарному электрическому заряду.", "Расписывать только 9 сильных кислот, щёлочи (Ca(OH)2/Sr(OH)2 слева) и растворимые соли («Р»)."]}}, {"id": "rio_conditions", "name": "Условия РИО, растворение осадков и гидроксокомплексы", "ref": "03", "idea": "Распознавать все три условия необратимости РИО (включая слабый электролит без газа), писать реакции растворения осадков и комплексообразования.", "pre": {"type": "one", "q": "Какая пара растворов реагирует с образованием СЛАБОГО ЭЛЕКТРОЛИТА без выпадения осадка и без выделения газа?", "o": ["KNO2 + H2SO4(разб.)", "K2SO3 + H2SO4(разб.)", "BaCl2 + Na2SO4", "NaCl + KNO3"], "a": 0, "ex": "2KNO2 + H2SO4(разб.) → 2HNO2 + K2SO4 (СИУ: H^{+} + NO2^{−} → HNO2). Азотистая кислота HNO2 — слабый растворимый электролит, осадка и газа нет (эталон Демо-2027).", "d": {"1": "K2SO3 + H2SO4 даёт газ SO2↑ (распад H2SO3).", "2": "BaCl2 + Na2SO4 даёт белый осадок BaSO4↓.", "3": "NaCl + KNO3 вообще не реагируют (нет осадка, газа или слабого электролита)."}}, "pair": {"type": "one", "cases": [["AlCl3 + избыток NaOH", "Сильная щёлочь переводит осадок Al(OH)3 в растворимый комплекс"], ["AlCl3 + избыток NH3·H2O", "Водный аммиак — слабое основание"]], "q": "Чем отличаются конечные продукты этих двух реакций?", "o": ["В избытке NaOH осадок растворяется до Na[Al(OH)4], а в избытке NH3·H2O остаётся белый осадок Al(OH)3↓", "В обоих случаях образуется растворимый гидроксокомплекс алюминия", "В обоих случаях выпадает осадок Al(OH)3↓ и не растворяется", "Во втором случае образуется аммиачный комплекс [Al(NH3)6](OH)3"], "a": 0, "ex": "Al(OH)3 растворяется только в сильных щелочах (NaOH, KOH, Ba(OH)2), а в водном аммиаке NH3·H2O не растворяется и аммиакатов не образует."}, "fade": {"q": "Восстанови ключевые правила растворения осадков и комплексов в РИО:", "steps": ["При растворении Al(OH)3 в избытке NaOH образуется комплекс Na[Al(OH)4], который в ПИУ расписывается как {Na^{+} + [Al(OH)4]^{−}|Na^{+} + Al^{3+} + 4OH^{−}|Na[Al(OH)4] (молекулой)}.", "При добавлении НЕДОСТАТКА HCl к раствору Na[Al(OH)4] выпадает осадок {Al(OH)3↓|AlCl3↓|NaCl↓}, а в ИЗБЫТКЕ HCl образуется раствор {AlCl3 + NaCl|Al(OH)3↓|NaAlO2}.", "При сливании растворов AgNO3 и NaOH вместо несуществующего AgOH выпадает тёмно-бурый осадок {Ag2O↓|Ag↓|Ag2O2↓}."]}, "bug": {"q": "Найди ошибочный шаг в анализе условий РИО:", "steps": ["Сульфит бария BaSO3 легко растворяется в соляной кислоте HCl с выделением газа SO2↑.", "Сульфат бария BaSO4 также растворяется в соляной кислоте HCl, так как HCl — сильная кислота.", "Силикат натрия Na2SiO3 реагирует с HCl с выпадением студенистого осадка слабой нерастворимой кислоты H2SiO3↓.", "В РИО двух солей обе исходные соли обязаны иметь статус «Р» в таблице растворимости ФИПИ."], "bad": 1, "fix": "BaSO4 (соль сильной H2SO4) не растворяется ни в HCl, ни в HNO3. В сильных кислотах растворяются осадки гидроксидов и солей слабых кислот (BaCO3, BaSO3, CaCO3, FeS, Ag3PO4).", "why": "Путаница BaSO3 (растворим в HCl) и BaSO4 (не растворим в кислотах) — частая ловушка в № 6 и № 30."}, "recall": {"q": "Перечисли 4 основных газа РИО, 2 прочерка с OH⁻ (Ag⁺, Hg²⁺) и правило разрушения гидроксокомплексов кислотой.", "points": ["Четыре газа РИО: CO2↑ (без запаха), SO2↑ (резкий запах), H2S↑ (тухлые яйца), NH3↑ (резкий запах, со щёлочью при нагревании).", "2Ag^{+} + 2OH^{−} → Ag2O↓ + H2O; Hg^{2+} + 2OH^{−} → HgO↓ + H2O.", "Разрушение [Al(OH)4]^{−}: с недостатком H^{+} → Al(OH)3↓ + H2O; с избытком 4H^{+} → Al^{3+} + 4H2O."]}}, {"id": "acid_salts_rio", "name": "Кислые соли в РИО: избыток/недостаток и HSO4⁻", "ref": "04", "idea": "Правильно диссоциировать кислые соли в ПИУ, различать избыток/недостаток с Ba(OH)2 и согласованно оформлять HSO4⁻.", "pre": {"type": "one", "q": "Какое сокращённое ионное уравнение (СИУ) соответствует реакции Ba(OH)2 + NaHCO3 в соотношении 1:1 (избыток щёлочи Ba(OH)2)?", "o": ["Ba^{2+} + OH^{−} + HCO3^{−} → BaCO3↓ + H2O", "Ba^{2+} + 2OH^{−} + 2HCO3^{−} → BaCO3↓ + CO3^{2−} + 2H2O", "Ba^{2+} + CO3^{2−} → BaCO3↓", "H^{+} + OH^{−} → H2O"], "a": 0, "ex": "МУ: Ba(OH)2 + NaHCO3 → BaCO3↓ + NaOH + H2O. В ПИУ один из двух OH^{−} сокращается с NaOH справа, остаётся Ba^{2+} + OH^{−} + HCO3^{−} → BaCO3↓ + H2O.", "d": {"1": "Это СИУ для соотношения 1:2 (избыток NaHCO3), где образуются две соли: BaCO3↓ + Na2CO3.", "2": "Нельзя расписывать кислый анион HCO3^{−} на H^{+} и CO3^{2−}!", "3": "Ионы Ba^{2+} и HCO3^{−} участвуют в образовании осадка BaCO3↓ и не могут исчезнуть."}}, "pair": {"type": "one", "cases": [["Гидрокарбонат натрия NaHCO3", "Кислая соль слабой угольной кислоты H2CO3"], ["Гидросульфат натрия NaHSO4", "Кислая соль сильной серной кислоты H2SO4"]], "q": "В чём принципиальное отличие записи анионов HCO3⁻ и HSO4⁻ в ПИУ по критериям ФИПИ?", "o": ["HCO3^{−} писать как H^{+} + CO3^{2−} ЗАПРЕЩЕНО; для HSO4^{−} допустимы оба варианта (целый HSO4^{−} или H^{+} + SO4^{2−}), но строго согласованно слева и справа", "Оба аниона всегда расписывают на H^{+} и средний анион", "Оба аниона строго запрещено расписывать на ионы", "HCO3^{−} расписывают на H^{+} + CO3^{2−}, а HSO4^{−} — нет"], "a": 0, "ex": "Кислые анионы слабых/средних кислот (HCO3^{−}, HSO3^{−}, HS^{−}, H2PO4^{−}, HPO4^{2−}) всегда единые ионы. У HSO4^{−} K_a2 ≈ 1,2·10⁻², поэтому ФИПИ принимает оба согласованных варианта."}, "fade": {"q": "Собери три типовые реакции с кислыми солями:", "steps": ["При сливании растворов NaH2PO4 и Na3PO4 происходит перераспределение протонов с образованием {2Na2HPO4|H3PO4 + Na2O|осадка Na3PO4↓}.", "Гидросульфат NaHSO4 с BaCl2 в каноническом соотношении 1:1 даёт {BaSO4↓ + NaCl + HCl|BaSO4↓ + Na2SO4 + HCl|реакция не идёт}.", "Фосфит натрия Na2HPO3 и гипофосфит NaH2PO2 — это {средние соли (со щёлочью не реагируют)|кислые соли (реагируют с NaOH)|основные соли}."]}, "bug": {"q": "Найди ошибку в оформлении реакции NaHSO4 + BaCl2 → BaSO4↓ + NaCl + HCl:", "steps": ["Молекулярное уравнение в соотношении 1:1: NaHSO4 + BaCl2 → BaSO4↓ + NaCl + HCl.", "Поскольку HSO4^{−} можно оставить целым, запишем ПИУ: Na^{+} + HSO4^{−} + Ba^{2+} + 2Cl^{−} → BaSO4↓ + Na^{+} + H^{+} + 2Cl^{−}.", "В этом ПИУ сокращаем Na^{+} и 2Cl^{−} и получаем СИУ: Ba^{2+} + SO4^{2−} → BaSO4↓.", "Оба варианта (с целым HSO4^{−} и с распадом H^{+} + SO4^{2−}) требуют строгой согласованности баланса атомов и зарядов."], "bad": 2, "fix": "Если слева оставлен целый HSO4^{−}, то в СИУ получится Ba^{2+} + HSO4^{−} → BaSO4↓ + H^{+}. Запись Ba^{2+} + SO4^{2−} → BaSO4↓ верна только если в ПИУ слева NaHSO4 был расписан как Na^{+} + H^{+} + SO4^{2−}.", "why": "Несогласованность ПИУ и СИУ для HSO4^{−} нарушает баланс водорода и зарядов."}, "recall": {"q": "Назови 2 варианта реакции Ba(OH)2 + NaHCO3 (1:1 и 1:2) и объясни, почему Na2HPO3 и NaH2PO2 не кислые соли.", "points": ["1:1 (изб. Ba(OH)2): Ba(OH)2 + NaHCO3 → BaCO3↓ + NaOH + H2O (образуется осадок и щёлочь).", "1:2 (изб. NaHCO3): Ba(OH)2 + 2NaHCO3 → BaCO3↓ + Na2CO3 + 2H2O (образуются две соли).", "H3PO3 — двухосновная кислота, H3PO2 — одноосновная (атомы H, связанные с P, не замещаются на металл), поэтому Na2HPO3 и NaH2PO2 — средние соли."]}}, {"id": "joint_hydrolysis_30", "name": "Совместный гидролиз, граница РИО/ОВР и критерии № 30", "ref": "05", "idea": "Уверенно отличать совместный гидролиз (РИО) от скрытых ОВР, знать запрещённые типы реакций в № 30 и набирать 2/2 балла.", "pre": {"type": "one", "q": "Какую из этих пар растворов с прочерком «–» в таблице ФИПИ МОЖНО выбрать для задания № 30 (РИО)?", "o": ["FeCl3 + NaHCO3", "FeCl3 + Na2S", "FeCl3 + Na2SO3", "CuSO4 + KI"], "a": 0, "ex": "В паре FeCl3 + 3NaHCO3 → Fe(OH)3↓ + 3CO2↑ + 3NaCl углерод в CO3^{2−}/HCO3^{−} имеет высшую СО (+4) и не окисляется — это совместный гидролиз (РИО).", "d": {"1": "Fe^{3+} окисляет S^{2−} до S↓ (ОВР, запрещено в № 30).", "2": "Fe^{3+} окисляет SO3^{2−} до SO4^{2−} (ОВР, запрещено в № 30).", "3": "Cu^{2+} окисляет I^{−} до I2 с выпадением CuI↓ (ОВР, запрещено в № 30)."}}, "pair": {"type": "one", "cases": [["2AlCl3 + 3Na2CO3 + 3H2O → 2Al(OH)3↓ + 3CO2↑ + 6NaCl", "Реакция с карбонатом CO3^{2−}"], ["FeCl3 + 3NaHCO3 → Fe(OH)3↓ + 3CO2↑ + 3NaCl", "Реакция с гидрокарбонатом HCO3^{−}"]], "q": "Почему в первом уравнении слева нужна вода (+ 3H2O), а во втором воды в уравнении нет?", "o": ["В 3HCO3^{−} уже ровно 3 атома H — столько же, сколько нужно для Fe(OH)3, поэтому баланс H и O сходится без воды", "Во втором уравнении вода тоже нужна, её просто опускают для краткости", "Гидрокарбонаты вообще не участвуют в совместном гидролизе", "Железо(+3) не требует воды для образования Fe(OH)3"], "a": 0, "ex": "Проверяем баланс: в Fe^{3+} + 3HCO3^{−} → Fe(OH)3↓ + 3CO2↑ слева 3 H и 9 O, справа 3 H и 3 + 6 = 9 O. Лишняя вода нарушила бы баланс."}, "fade": {"q": "Отфильтруй допустимые и запрещённые реакции для задания № 30:", "steps": ["В реакции K2Cr2O7 + 2KOH → 2K2CrO4 + H2O степень окисления хрома {не меняется (+6) — это РИО|понижается — это ОВР|повышается — это ОВР}.", "Реакция CaO + 2HCl → CaCl2 + H2O в № 30 {запрещена (CaO — оксид, неэлектролит)|разрешена как растворение осадка|разрешена при нагревании}.", "Реакция NaCl(тв.) + H2SO4(конц.) —t°→ NaHSO4 + HCl↑ в № 30 {запрещена (не РИО в водном растворе)|разрешена (выделяется газ HCl↑)|разрешена как реакция с кислой солью}."]}, "bug": {"q": "Найди ошибку в отборе пары веществ для задания № 30 (перечень: Al2(SO4)3, FeCl3, Na2S, K2CO3, BaO, HNO3; условие: «осадок и газ с запахом тухлых яиц»):", "steps": ["Газ с запахом тухлых яиц — это сероводород H2S↑, значит нужен сульфид Na2S.", "Оксид BaO сразу отбрасываем, так как оксиды — неэлектролиты и запрещены в № 30.", "Берём пару FeCl3 + Na2S, чтобы получить бурый осадок Fe(OH)3↓ и газ H2S↑.", "Для совместного гидролиза с Na2S подходит соль алюминия Al2(SO4)3, дающая Al(OH)3↓ и H2S↑."], "bad": 2, "fix": "FeCl3 + Na2S — это ОВР (Fe^{+3} окисляет S^{−2} до серы S↓), а не совместный гидролиз! Нужно выбрать Al2(SO4)3 + 3Na2S + 6H2O → 2Al(OH)3↓ + 3H2S↑ + 3Na2SO4.", "why": "Выбор ОВР вместо РИО в задании № 30 мгновенно даёт 0 баллов за всё задание."}, "recall": {"q": "Назови 4 категории реакций, запрещённых в № 30, и 2 разрешённые реакции перехода хромат ↔ дихромат.", "points": ["Запрещены в № 30: (1) любые ОВР (в т.ч. скрытые Fe^{3+}+S^{2−}/SO3^{2−}/I^{−}, Cu^{2+}+I^{−}), (2) оксиды и простые вещества, (3) твёрдые соли с H2SO4(конц.), (4) обмен двух солей с «Н»/«М»/«–» слева.", "Дихромат → хромат (оранжевый → жёлтый): Cr2O7^{2−} + 2OH^{−} → 2CrO4^{2−} + H2O.", "Хромат → дихромат (жёлтый → оранжевый): 2CrO4^{2−} + 2H^{+} → Cr2O7^{2−} + H2O."]}}, {"id": "kim6_tubes", "name": "Пробирки X и Y: качественные признаки РИО в № 6", "ref": "06", "idea": "Безошибочно расшифровывать реагенты X и Y по цвету и растворимости осадков, запаху газов и «тихим» реакциям, соблюдая порядок цифр.", "pre": {"type": "one", "q": "В пробирке находится белый осадок BaCO3. Какую кислоту нужно выбрать для ПОЛНОГО растворения этого осадка с выделением газа без запаха?", "o": ["HCl", "H2SO4", "H2SiO3", "H2S"], "a": 0, "ex": "BaCO3 + 2HCl → BaCl2 + CO2↑ + H2O: осадок полностью растворяется, так как BaCl2 растворим («Р»).", "d": {"1": "С H2SO4 образуется новый нерастворимый осадок BaSO4↓ — полного растворения не будет!", "2": "H2SiO3 сама нерастворима и слабее угольной кислоты.", "3": "H2S — слабая кислота и с осадком BaCO3 не реагирует."}}, "pair": {"type": "one", "cases": [["Осадок Cu(OH)2 (голубой)", "Основной гидроксид"], ["Осадок Cr(OH)3 (серо-зелёный)", "Амфотерный гидроксид"]], "q": "Как эти два осадка ведут себя при добавлении избытка водного раствора KOH?", "o": ["Cu(OH)2 не растворяется, а Cr(OH)3 растворяется с образованием зелёного раствора комплексной соли", "Оба осадка растворяются в водном растворе KOH", "Ни один из осадков не растворяется в водном растворе KOH", "Cu(OH)2 растворяется, а Cr(OH)3 не растворяется"], "a": 0, "ex": "Cu(OH)2 и Fe(OH)3 не амфотерны в водных щелочах и не растворяются в KOH, а амфотерный Cr(OH)3 образует растворимый гидроксокомплекс K3[Cr(OH)6] / K[Cr(OH)4]."}, "fade": {"q": "Расшифруй классические качественные признаки из задания № 6:", "steps": ["Жёлтый осадок {Ag3PO4|AgI|AgCl} растворяется в разбавленной HNO3, а жёлтый осадок {AgI|Ag3PO4|BaCrO4} в HNO3 не растворяется.", "Чёрный сульфид {FeS|CuS|Ag2S} растворяется в разбавленной HCl с выделением H2S↑, а чёрный сульфид {CuS|FeS|ZnS} в разбавленной HCl не растворяется.", "Если при добавлении вещества Y к раствору KOH реакция прошла БЕЗ видимых признаков, то Y может быть кислой солью {KHCO3|CuSO4|FeCl3} (образуется H2O)."]}, "bug": {"q": "Найди ошибку в решении задачи № 6 (две пробирки с раствором Na2CO3: с X выпал белый осадок без газа; с Y выпал белый осадок и выделился газ без запаха; список: 1-HCl, 2-Ba(NO3)2, 3-AlCl3, 4-K2SO4, 5-NaOH):", "steps": ["С Ba(NO3)2 (2) выпадает белый осадок BaCO3↓ без выделения газа → X = 2.", "С HCl (1) выделяется газ CO2↑, но осадка нет — отбрасываем.", "С AlCl3 (3) идёт совместный гидролиз: белый осадок Al(OH)3↓ + газ CO2↑ → Y = 3.", "Поскольку оба вещества найдены верно, в бланк можно записать 32 — порядок цифр не влияет на баллы."], "bad": 3, "fix": "В задании № 6 порядок цифр строго фиксирован (сначала X, потом Y → 23). Запись 32 даёт 0 баллов из 2, так как не совпадает ни одна позиция.", "why": "Перестановка X и Y местами — самая обидная причина потери сразу 2 первичных баллов в № 6."}, "recall": {"q": "Назови цвета 4 гидроксидов (Cu(OH)2, Fe(OH)3, Cr(OH)3, Al(OH)3) и 3 примера реакций «без видимых признаков» в № 6.", "points": ["Cu(OH)2 — голубой, Fe(OH)3 — бурый, Cr(OH)3 — серо-зелёный (амфотерный), Al(OH)3 — белый студенистый (амфотерный).", "Реакции без видимых признаков: нейтрализация сильной кислоты щёлочью (H^{+} + OH^{−} → H2O), нейтрализация кислой соли щёлочью (HCO3^{−} + OH^{−} → CO3^{2−} + H2O), образование растворимой слабой кислоты (NO2^{−} + H^{+} → HNO2) или NH3·H2O на холоду."]}}, {"id": "hydrolysis_4types", "name": "Гидролиз 4 типов солей, 1-я ступень и смещение равновесия", "ref": "07", "idea": "Определять тип гидролиза и среду любых солей (включая ловушки Mg²⁺, CH3COONH4, нерастворимые соли), писать 1-ю ступень и смещать равновесие.", "pre": {"type": "one", "q": "Какую среду имеет водный раствор хлорида магния MgCl2 и почему?", "o": ["Кислую (гидролиз по катиону Mg^{2+}, так как Mg(OH)2 — слабое нерастворимое основание)", "Нейтральную (Mg стоит во IIА группе, как Ca и Ba, гидролиза нет)", "Щелочную (гидролиз по аниону Cl^{−})", "Нейтральную, так как MgCl2 нерастворим в воде"], "a": 0, "ex": "MgCl2 — растворимая соль слабого основания Mg(OH)2 и сильной кислоты HCl → гидролиз по катиону Mg^{2+} + H2O ⇄ MgOH^{+} + H^{+} → среда кислая (pH < 7).", "d": {"1": "Ловушка IIА группы! Щёлочи образуют Ca, Sr, Ba, но НЕ магний (Mg(OH)2 — слабое основание).", "2": "Cl^{−} — анион сильной кислоты HCl, он не гидролизуется.", "3": "По таблице ФИПИ MgCl2 хорошо растворим («Р»)."}}, "pair": {"type": "one", "cases": [["Сульфат калия K2SO4 и нитрат натрия NaNO3", "Анионы сильных кислот H2SO4 и HNO3"], ["Сульфит калия K2SO3 и нитрит натрия NaNO2", "Анионы слабых кислот H2SO3 и HNO2"]], "q": "Какова среда водных растворов первой и второй пары солей?", "o": ["Первая пара — нейтральная (гидролиза нет), вторая пара — щелочная (гидролиз по аниону)", "Обе пары — нейтральная, так как все соли содержат K^{+} и Na^{+}", "Первая пара — кислая, вторая пара — щелочная", "Обе пары — щелочная, так как во всех анионах есть кислород"], "a": 0, "ex": "SO4^{2−} и NO3^{−} — анионы сильных кислот (не гидролизуются, pH = 7), а SO3^{2−} и NO2^{−} — анионы слабых кислот (гидролиз по аниону, pH > 7)."}, "fade": {"q": "Определи сдвиг равновесия обратимого гидролиза солей по принципу Ле Шателье:", "steps": ["При нагревании обратимый гидролиз любой соли {усиливается (процесс эндотермичен, −Q)|ослабевает|не меняется}.", "При разбавлении раствора водой степень гидролиза {увеличивается|уменьшается|не меняется}.", "Добавление сильной кислоты HCl к раствору AlCl3 (гидролиз по катиону) гидролиз {подавляет (избыток H^{+} сдвигает влево)|усиливает|не изменяет}, а к раствору Na2CO3 (по аниону) — {усиливает (H^{+} связывает OH^{−})|подавляет|не изменяет}."]}, "bug": {"q": "Найди ошибочное утверждение о гидролизе солей:", "steps": ["Обратимый гидролиз AlCl3 в растворе идёт преимущественно по 1-й ступени: Al^{3+} + H2O ⇄ AlOH^{2+} + H^{+}.", "Карбонат кальция CaCO3 образован сильным основанием Ca(OH)2 и слабой кислотой H2CO3, поэтому в воде он активно гидролизуется по аниону и даёт сильнощелочную среду.", "Ацетат аммония CH3COONH4 гидролизуется обратимо по катиону и аниону, но среда раствора близка к нейтральной (pH ≈ 7).", "Сухой сульфид алюминия Al2S3 при попадании в воду подвергается необратимому гидролизу до Al(OH)3↓ и H2S↑."], "bad": 1, "fix": "CaCO3 нерастворим в воде («Н» в таблице ФИПИ), поэтому его ионы практически не переходят в раствор — в рамках ЕГЭ нерастворимые соли гидролизу не подвергаются.", "why": "Перед определением типа гидролиза всегда проверяй растворимость соли!"}, "recall": {"q": "Сформулируй 4 типа солей по гидролизу и приведи уравнения 1-й ступени для AlCl3 и Na2CO3.", "points": ["1) Сильное + сильная (NaCl) — нет гидролиза (pH = 7); 2) Слабое + сильная (AlCl3) — по катиону (pH < 7); 3) Сильное + слабая (Na2CO3) — по аниону (pH > 7); 4) Слабое + слабая — по обоим ионам (CH3COONH4 обратимо, Al2S3 необратимо).", "Al^{3+} + H2O ⇄ AlOH^{2+} + H^{+} (AlCl3 + H2O ⇄ AlOHCl2 + HCl).", "CO3^{2−} + H2O ⇄ HCO3^{−} + OH^{−} (Na2CO3 + H2O ⇄ NaHCO3 + NaOH)."]}}, {"id": "ph_scale_acid_salts", "name": "Kw, шкала pH, индикаторы и 6 кислых солей", "ref": "08", "idea": "Переводить [H⁺] в pH, знать окраску индикаторов, безошибочно делить 6 кислых солей на кислые и щелочные и сравнивать вещества равной концентрации.", "pre": {"type": "one", "q": "Какие две кислые соли в водном растворе имеют СЛАБОЩЕЛОЧНУЮ среду (pH > 7)?", "o": ["NaHCO3 и Na2HPO4", "NaH2PO4 и NaHSO3", "NaHSO4 и NaHCO3", "NaH2PO4 и NaHSO4"], "a": 0, "ex": "У NaHCO3, Na2HPO4 и NaHS гидролиз аниона преобладает над диссоциацией → среда слабощелочная (pH > 7).", "d": {"1": "У NaH2PO4 и NaHSO3 преобладает диссоциация → среда слабокислая (pH < 7).", "2": "NaHSO4 имеет сильнокислую среду (pH ≈ 1–2).", "3": "Обе соли дают кислую среду."}}, "pair": {"type": "one", "cases": [["0,1 М раствор H2SO4 и 0,1 М раствор HCl", "Две сильные кислоты одинаковой молярной концентрации"], ["0,1 М раствор Ba(OH)2 и 0,1 М раствор NaOH", "Две щёлочи одинаковой молярной концентрации"]], "q": "Какое соотношение значений pH верно для этих пар растворов?", "o": ["pH(H2SO4) < pH(HCl) и pH(NaOH) < pH(Ba(OH)2)", "pH(H2SO4) = pH(HCl) и pH(NaOH) = pH(Ba(OH)2)", "pH(H2SO4) > pH(HCl) и pH(NaOH) > pH(Ba(OH)2)", "pH(H2SO4) < pH(HCl) и pH(NaOH) > pH(Ba(OH)2)"], "a": 0, "ex": "Двухосновная H2SO4 даёт больше H^{+} → pH ниже; двухкислотная щёлочь Ba(OH)2 даёт 2OH^{−} → pH выше."}, "fade": {"q": "Проверь работу с шкалой pH, индикаторами и сравнением растворов:", "steps": ["Если концентрация [H^{+}] увеличилась в 100 раз, то значение pH {уменьшилось на 2|увеличилось на 2|уменьшилось в 100 раз}.", "Индикатор {фенолфталеин|лакмус|метилоранж} бесцветен и в кислой, и в нейтральной среде, но становится малиновым в щелочной.", "Чем слабее кислота, тем {сильнее|слабее|одинаково} гидролиз её натриевой соли и тем {выше|ниже|ближе к 7} значение pH раствора."]}, "bug": {"q": "Найди ошибку в сравнении pH водных растворов одинаковой молярной концентрации:", "steps": ["У сильной кислоты HCl pH ниже, чем у слабой кислоты CH3COOH.", "У слабой кислоты CH3COOH pH ниже, чем у соли NH4Cl, гидролизующейся по катиону.", "У кислой соли NaH2PO4 среда слабокислая (pH < 7), а у Na2HPO4 — слабощелочная (pH > 7).", "У кислой соли NaHCO3 среда кислая, так как в её формуле есть атом водорода, поэтому pH(NaHCO3) < 7."], "bad": 3, "fix": "У NaHCO3 (пищевой соды) гидролиз аниона HCO3^{−} + H2O ⇄ H2CO3 + OH^{−} преобладает над диссоциацией, поэтому среда слабощелочная (pH ≈ 8,3 > 7).", "why": "Автоматический вывод «кислая соль = кислая среда» — самая частая ловушка задания № 21."}, "recall": {"q": "Раздели по памяти 6 кислых солей на две тройки по среде и назови окраску лакмуса, метилоранжа и фенолфталеина в 3 средах.", "points": ["Кислая среда (pH < 7): NaHSO4 (сильнокислая), NaH2PO4 (слабокислая), NaHSO3 (слабокислая).", "Щелочная среда (pH > 7): NaHCO3, Na2HPO4, NaHS (все слабощелочные).", "Лакмус: кр / фиол / син; Метилоранж: кр / ор / жёлт; Фенолфталеин: бесцв / бесцв / малиновый."]}}, {"id": "kim21_ranking", "name": "Ранжирование неорганических и органических растворов (№ 21)", "ref": "09", "idea": "За 40 секунд расставлять любые 4 раствора (включая органику и похожие названия солей) по возрастанию или убыванию pH без потери единственного балла.", "pre": {"type": "one", "q": "Какую среду имеют водные растворы фенолята натрия C6H5ONa и хлорида метиламмония CH3NH3Cl соответственно?", "o": ["Щелочную (pH > 7) и кислую (pH < 7)", "Кислую (pH < 7) и щелочную (pH > 7)", "Оба раствора имеют нейтральную среду", "Оба раствора имеют щелочную среду"], "a": 0, "ex": "C6H5ONa — соль сильного основания NaOH и очень слабой кислоты (фенола) → гидролиз по аниону (pH > 7). CH3NH3Cl — соль слабого основания (метиламина) и сильной HCl → гидролиз по катиону (pH < 7).", "d": {"1": "Перепутан тип гидролиза: фенолят гидролизуется по аниону, соль амина — по катиону.", "2": "Обе соли подвергаются гидролизу.", "3": "Соли аминов (как и соли аммония NH4Cl) дают кислую среду."}}, "pair": {"type": "one", "cases": [["Метиламин CH3NH2 (водный раствор)", "Алифатический амин (электронодонорная группа −CH3 усиливает основность)"], ["Анилин C6H5NH2 (водный раствор)", "Ароматический амин (бензольное кольцо оттягивает электронную пару азота)"]], "q": "Какова среда водных растворов метиламина и анилина в задании № 21?", "o": ["CH3NH2 — слабощелочная (pH > 7), анилин C6H5NH2 — практически нейтральная (pH ≈ 7)", "Оба раствора имеют выраженную щелочную среду (pH ≈ 11)", "Анилин щелочнее метиламина", "Оба раствора имеют кислую среду"], "a": 0, "ex": "Алифатические амины сильнее аммиака и окрашивают индикаторы в щелочной цвет, а анилин настолько слабое основание, что индикаторы в его растворе цвет не меняют (pH ≈ 7)."}, "fade": {"q": "Распредели органические соединения по этажам pH для № 21:", "steps": ["Этанол C2H5OH, глюкоза и глицин NH2CH2COOH дают {нейтральную (pH ≈ 7)|кислую|щелочную} среду.", "Среди кислот одинаковой концентрации pH убывает в ряду C6H5OH > CH3COOH > HCOOH, значит самая сильная из них — {HCOOH (муравьиная)|CH3COOH (уксусная)|C6H5OH (фенол)}.", "Этилат натрия C2H5ONa в воде гидролизуется необратимо до {NaOH + C2H5OH (сильнощелочная среда)|нейтрального раствора|кислой среды}."]}, "bug": {"q": "Найди ошибку в решении задания № 21: «Расположите в порядке УБЫВАНИЯ pH: (1) CH3COOH, (2) C2H5OH, (3) CH3COONa, (4) KOH»:", "steps": ["Переводим в этажи pH: KOH ≈ 13 (щёлочь), CH3COONa ≈ 8,9 (гидролиз по аниону), C2H5OH = 7 (неэлектролит), CH3COOH ≈ 2,9 (слабая кислота).", "Сравниваем значения pH: CH3COOH < C2H5OH < CH3COONa < KOH.", "Записываем ответ в бланк: 1234.", "За № 21 дают 1 балл только при 100% совпадении всех четырёх цифр."], "bad": 2, "fix": "В условии требуется порядок УБЫВАНИЯ pH (от щёлочи к кислоте): KOH > CH3COONa > C2H5OH > CH3COOH → верный ответ 4321, а не 1234!", "why": "До трети ошибок в № 21 связаны с тем, что ученик записал ряд по возрастанию вместо убывания."}, "recall": {"q": "Назови 4-шаговый алгоритм решения № 21 и приведи порядок возрастания pH для ряда фосфатов (H3PO4, NaH2PO4, Na2HPO4, Na3PO4).", "points": ["Алгоритм: (1) перевести русские названия в формулы, (2) определить этаж pH каждого вещества, (3) развести соседей внутри этажа, (4) дважды проверить направление (возрастание ↑ или убывание ↓).", "Ряд фосфатов по возрастанию pH: H3PO4 < NaH2PO4 (<7) < Na2HPO4 (>7) < Na3PO4."]}}], "figs": {}, "tab": [{"id": "tab_electrolytes", "ref": "01.21", "k": "Вещество (водный раствор / осадок)", "km": "веществом", "lv3": ["CH3COONa", "H3PO4", "HNO2", "HF", "Ca(OH)2 (слева)", "Ca(OH)2 (справа)", "CaSO4"], "cols": [{"t": "Как записывать в ПИУ (№ 30)", "sk": "electrolytes", "n": 30, "q": "Как записывается {x} в полном ионном уравнении (ПИУ) задания № 30?", "m": "формой записи в ПИУ", "mq": "Выберите {k} вещества с правилом записи в ПИУ: {v}."}], "rows": [["HClO4", "Расписываем на ионы (сильный электролит)"], ["HNO3", "Расписываем на ионы (сильный электролит)"], ["CH3COONa", "Расписываем на ионы (сильный электролит)"], ["NH4Cl", "Расписываем на ионы (сильный электролит)"], ["Ca(OH)2 (слева)", "Расписываем на ионы (сильный электролит)"], ["H3PO4", "Пишем молекулой (слабый/средний электролит или осадок)"], ["HF", "Пишем молекулой (слабый/средний электролит или осадок)"], ["HNO2", "Пишем молекулой (слабый/средний электролит или осадок)"], ["CH3COOH", "Пишем молекулой (слабый/средний электролит или осадок)"], ["NH3·H2O", "Пишем молекулой (слабый/средний электролит или осадок)"], ["Ca(OH)2 (справа)", "Пишем молекулой (слабый/средний электролит или осадок)"], ["CaSO4", "Пишем молекулой (слабый/средний электролит или осадок)"]], "rw": {"CH3COONa": "Растворимая соль («Р») — всегда сильный электролит, даже от слабой кислоты.", "H3PO4": "Кислота средней силы — в 9 сильных кислот ЕГЭ не входит, пишется молекулой.", "HNO2": "Слабая кислота — эталонная ловушка Демо-2027 (№ 30).", "Ca(OH)2 (слева)": "Позиционное правило: известковая вода в реагентах расписывается на ионы.", "Ca(OH)2 (справа)": "Позиционное правило: выпадающий осадок Ca(OH)2↓ справа пишется молекулой.", "CaSO4": "Малорастворимые соли («М») не расписываются ни слева, ни справа."}}, {"id": "tab_fipi_traps", "ref": "02.9", "k": "Вещество в таблице ФИПИ-2027", "km": "веществом", "lv3": ["Ca(CH3COO)2", "Ba(HCO3)2", "Li3PO4", "Li2CO3", "AgF", "CaCrO4"], "cols": [{"t": "Статус в таблице растворимости ФИПИ-2027", "sk": "fipi_solubility_piu", "n": 30, "q": "Какой символ стоит у {x} в официальной таблице растворимости ФИПИ ЕГЭ-2027?", "m": "статусом в таблице ФИПИ", "mq": "Выберите {k} вещества со статусом «{v}» в таблице ФИПИ-2027."}], "rows": [["AgF", "«Р» (растворимо)"], ["CaCrO4", "«Р» (растворимо)"], ["Li2CO3", "«Р» (растворимо)"], ["Ca(HCO3)2", "«Р» (растворимо)"], ["CaSO4", "«М» (малорастворимо)"], ["Ag2SO4", "«М» (малорастворимо)"], ["PbCl2", "«М» (малорастворимо)"], ["LiF", "«М» (малорастворимо)"], ["Li3PO4", "«Н» (осадок)"], ["Li2SiO3", "«Н» (осадок)"], ["Ca(CH3COO)2", "«–» (прочерк в бланке ФИПИ)"], ["Ba(HCO3)2", "«–» (прочерк в бланке ФИПИ)"], ["(NH4)3PO4", "«–» (прочерк в бланке ФИПИ)"]], "rw": {"Ca(CH3COO)2": "Условность бланка ФИПИ-2027 — стоит «–», слева в № 30 не выбираем.", "Ba(HCO3)2": "В таблице ФИПИ среди щёлочноземельных гидрокарбонатов «Р» только у Ca(HCO3)2.", "Li3PO4": "В отличие от солей Na/K, фосфат и силикат лития нерастворимы («Н»).", "AgF": "Единственный хорошо растворимый галогенид серебра («Р»)."}}, {"id": "tab_rio_vs_ovr", "ref": "05.10", "k": "Пара реагентов в водном растворе", "km": "парой реагентов", "lv3": ["FeCl3 + Na2CO3", "FeCl3 + Na2S", "FeCl3 + Na2SO3", "CuSO4 + KI", "K2Cr2O7 + KOH"], "cols": [{"t": "Тип реакции и допуск в № 30", "sk": "joint_hydrolysis_30", "n": 30, "q": "К какому типу относится реакция {x} и можно ли её писать в задании № 30?", "m": "типом реакции и допуском в № 30", "mq": "Выберите {k} пары реагентов с характеристикой: {v}."}], "rows": [["AlCl3 + Na2CO3", "РИО — совместный гидролиз (МОЖНО в № 30)"], ["CrCl3 + Na2S", "РИО — совместный гидролиз (МОЖНО в № 30)"], ["Al2(SO4)3 + Na2SO3", "РИО — совместный гидролиз (МОЖНО в № 30)"], ["FeCl3 + Na2CO3", "РИО — совместный гидролиз (МОЖНО в № 30)"], ["FeCl3 + NaHCO3", "РИО — совместный гидролиз (МОЖНО в № 30)"], ["FeCl3 + Na2S", "Скрытая ОВР (ЗАПРЕЩЕНО в № 30)"], ["FeCl3 + Na2SO3", "Скрытая ОВР (ЗАПРЕЩЕНО в № 30)"], ["FeCl3 + KI", "Скрытая ОВР (ЗАПРЕЩЕНО в № 30)"], ["CuSO4 + KI", "Скрытая ОВР (ЗАПРЕЩЕНО в № 30)"], ["K2Cr2O7 + KOH", "РИО — переход хромат/дихромат (МОЖНО в № 30)"], ["K2CrO4 + H2SO4(разб.)", "РИО — переход хромат/дихромат (МОЖНО в № 30)"], ["CaO + HCl", "Не-РИО с оксидом (ЗАПРЕЩЕНО в № 30)"]], "rw": {"FeCl3 + Na2CO3": "C^{+4} не восстановитель → совместный гидролиз до Fe(OH)3↓ + CO2↑.", "FeCl3 + Na2S": "Fe^{+3} окисляет S^{−2} до S↓ → ОВР (относится к № 29).", "FeCl3 + Na2SO3": "Fe^{+3} окисляет S^{+4} до S^{+6} → ОВР (относится к № 29).", "K2Cr2O7 + KOH": "Степень окисления Cr (+6) не меняется — оранжевый раствор становится жёлтым."}}, {"id": "tab_kim6_signs", "ref": "06.7", "k": "Осадок или газ в задании № 6", "km": "веществом", "lv3": ["BaSO3↓", "Ag3PO4↓", "Cr(OH)3↓", "FeS↓", "CuS↓"], "cols": [{"t": "Цвет / запах и поведение", "sk": "kim6_tubes", "n": 6, "q": "Какой качественный признак характерен для {x} в задании № 6?", "m": "качественным признаком", "mq": "Выберите {k} вещества с признаком: {v}."}], "rows": [["BaSO4↓", "Белый осадок, НЕ растворим в HCl/HNO3"], ["AgCl↓", "Белый осадок, НЕ растворим в HCl/HNO3"], ["BaCO3↓", "Белый осадок, растворим в HCl с газом"], ["BaSO3↓", "Белый осадок, растворим в HCl с газом"], ["Al(OH)3↓", "Белый амфотерный осадок (растворим в HCl и NaOH)"], ["Zn(OH)2↓", "Белый амфотерный осадок (растворим в HCl и NaOH)"], ["Cu(OH)2↓", "Голубой осадок (не растворим в водном NaOH)"], ["Fe(OH)3↓", "Бурый осадок (не растворим в водном NaOH)"], ["Cr(OH)3↓", "Серо-зелёный амфотерный осадок (растворим в HCl и NaOH)"], ["AgI↓", "Жёлтый осадок, НЕ растворим в HNO3"], ["Ag3PO4↓", "Жёлтый осадок, растворим в HNO3"], ["CuS↓", "Чёрный осадок, НЕ растворим в разб. HCl"], ["FeS↓", "Чёрный осадок, растворим в разб. HCl с H2S↑"]], "rw": {"BaSO3↓": "Соль слабой H2SO3 — растворяется в HCl с выделением SO2↑ (в отличие от BaSO4).", "Ag3PO4↓": "В отличие от AgI/AgBr, фосфат серебра растворяется в HNO3.", "Cr(OH)3↓": "В отличие от Cu(OH)2 и Fe(OH)3, амфотерен и растворяется в щёлочи."}}, {"id": "tab_hydrolysis_salts", "ref": "07.6", "k": "Соль (водный раствор)", "km": "солью", "lv3": ["MgCl2", "CH3COONH4", "CaCO3", "Na2HPO3", "K2SO3", "NaNO2"], "cols": [{"t": "Тип гидролиза", "sk": "hydrolysis_4types", "n": 21, "q": "Как подвергается гидролизу {x} в воде?", "m": "типом гидролиза", "mq": "Выберите {k} соли с типом гидролиза: {v}."}, {"t": "Среда водного раствора", "sk": "hydrolysis_4types", "n": 21, "q": "Какова среда водного раствора {x}?", "m": "средой раствора", "mq": "Выберите {k} соли со средой раствора: {v}."}], "rows": [["NaCl", "Не гидролизуется", "Нейтральная (pH = 7)"], ["K2SO4", "Не гидролизуется", "Нейтральная (pH = 7)"], ["Ba(NO3)2", "Не гидролизуется", "Нейтральная (pH = 7)"], ["CaCO3", "Не гидролизуется (нерастворима)", "Нейтральная (pH = 7)"], ["NH4Cl", "По катиону", "Кислая (pH < 7)"], ["Al(NO3)3", "По катиону", "Кислая (pH < 7)"], ["CuSO4", "По катиону", "Кислая (pH < 7)"], ["MgCl2", "По катиону", "Кислая (pH < 7)"], ["Na2CO3", "По аниону", "Щелочная (pH > 7)"], ["K2SO3", "По аниону", "Щелочная (pH > 7)"], ["NaNO2", "По аниону", "Щелочная (pH > 7)"], ["CH3COONa", "По аниону", "Щелочная (pH > 7)"], ["Na2HPO3", "По аниону", "Щелочная (pH > 7)"], ["CH3COONH4", "По катиону и аниону (обратимо)", "Нейтральная (pH ≈ 7)"]], "rw": {"MgCl2": "Ловушка IIА группы: Mg(OH)2 — слабое основание → гидролиз по катиону (pH < 7).", "CH3COONH4": "K_a(CH3COOH) ≈ K_b(NH3·H2O) → среда близка к нейтральной.", "CaCO3": "Нерастворимые соли в воде не гидролизуются.", "Na2HPO3": "Средняя соль слабой двухосновной кислоты H3PO3 → гидролиз по аниону (pH > 7)."}}, {"id": "tab_acid_salts_ph", "ref": "08.16", "k": "Кислая соль щелочного металла", "km": "кислой солью", "lv3": ["NaHSO4", "NaH2PO4", "NaHSO3", "NaHCO3", "Na2HPO4", "NaHS"], "cols": [{"t": "Среда водного раствора в № 21", "sk": "ph_scale_acid_salts", "n": 21, "q": "Какую среду имеет водный раствор кислой соли {x} в задании № 21?", "m": "средой раствора", "mq": "Выберите {k} кислые соли со средой: {v}."}, {"t": "Какой процесс преобладает в воде", "sk": "ph_scale_acid_salts", "n": 21, "q": "Какой процесс преобладает в водном растворе {x}?", "m": "преобладающим процессом", "mq": "Выберите {k} кислые соли, у которых преобладает: {v}."}], "rows": [["NaHSO4", "Сильнокислая (pH ≈ 1–2)", "Диссоциация кислого аниона"], ["KHSO4", "Сильнокислая (pH ≈ 1–2)", "Диссоциация кислого аниона"], ["NaH2PO4", "Слабокислая (pH < 7)", "Диссоциация кислого аниона"], ["NaHSO3", "Слабокислая (pH < 7)", "Диссоциация кислого аниона"], ["NaHCO3", "Слабощелочная (pH > 7)", "Гидролиз кислого аниона"], ["Na2HPO4", "Слабощелочная (pH > 7)", "Гидролиз кислого аниона"], ["NaHS", "Слабощелочная (pH > 7)", "Гидролиз кислого аниона"]], "rw": {"NaHSO4": "HSO4^{−} активно отдаёт H^{+} и почти не гидролизуется.", "NaH2PO4": "Диссоциация H2PO4^{−} ⇄ H^{+} + HPO4^{2−} сильнее гидролиза → слабокислая.", "NaHCO3": "Гидролиз HCO3^{−} + H2O ⇄ H2CO3 + OH^{−} сильнее диссоциации → слабощелочная.", "Na2HPO4": "Гидролиз HPO4^{2−} сильнее третьей ступени диссоциации → слабощелочная."}}, {"id": "tab_organics_21", "ref": "09.4", "k": "Органическое вещество (водный раствор)", "km": "органическим веществом", "lv3": ["C6H5OH (фенол)", "C6H5NH2 (анилин)", "NH2CH2COOH (глицин)", "C2H5ONa", "CH3NH3Cl"], "cols": [{"t": "Среда водного раствора в № 21", "sk": "kim21_ranking", "n": 21, "q": "Какую среду имеет водный раствор {x} в задании № 21?", "m": "средой раствора", "mq": "Выберите {k} вещества со средой раствора: {v}."}], "rows": [["HCOOH (муравьиная к-та)", "Слабокислая (pH < 7)"], ["CH3COOH (уксусная к-та)", "Слабокислая (pH < 7)"], ["C6H5OH (фенол)", "Очень слабокислая (pH < 7)"], ["CH3NH3Cl (хлорид метиламмония)", "Слабокислая (pH < 7)"], ["C2H5OH (этанол)", "Нейтральная (pH ≈ 7)"], ["C6H12O6 (глюкоза)", "Нейтральная (pH ≈ 7)"], ["NH2CH2COOH (глицин)", "Нейтральная (pH ≈ 7)"], ["C6H5NH2 (анилин)", "Нейтральная (pH ≈ 7)"], ["CH3NH2 (метиламин)", "Слабощелочная (pH > 7)"], ["CH3COONa (ацетат натрия)", "Слабощелочная (pH > 7)"], ["C6H5ONa (фенолят натрия)", "Щелочная (pH > 7)"], ["C2H5ONa (этилат натрия)", "Сильнощелочная (pH ≈ 13, как у NaOH)"]], "rw": {"C6H5NH2 (анилин)": "Бензольное кольцо резко ослабляет основность — индикаторы не меняют цвет.", "NH2CH2COOH (глицин)": "Одна группа −NH2 и одна −COOH компенсируют друг друга.", "C2H5ONa": "Алкоголят в воде необратимо гидролизуется: C2H5ONa + H2O → C2H5OH + NaOH."}}], "rx": [{"id": "rx01_caoh2_hcl", "sk": "fipi_solubility_piu", "ref": "02.13", "n": 30, "lvl": 1, "l": ["Ca(OH)2", "HCl"], "r": ["CaCl2", "H2O"], "c": [1, 2, 1, 2], "if": "известковая вода (Ca(OH)2 слева расписывается на ионы; СИУ: H^{+} + OH^{−} → H2O)", "bad": [["CaO", "В водном растворе образуются соль CaCl2 и вода, а не оксид кальция."], ["H2", "Это реакция нейтрализации (РИО), а не реакция металла с кислотой."]], "why": "По позиционному правилу ФИПИ Ca(OH)2 слева расписывается на Ca^{2+} + 2OH^{−}, поэтому СИУ сводится к H^{+} + OH^{−} → H2O."}, {"id": "rx02_cacl2_naoh", "sk": "fipi_solubility_piu", "ref": "02.14", "n": 30, "lvl": 2, "l": ["CaCl2", "NaOH"], "r": ["Ca(OH)2", "NaCl"], "c": [1, 2, 1, 2], "if": "конц. растворы (Ca(OH)2↓ справа пишется молекулой; СИУ: Ca^{2+} + 2OH^{−} → Ca(OH)2↓)", "bad": [["CaO", "Гидроксид кальция в воде не разлагается до оксида (в отличие от AgOH)."], ["Na2CaO2", "Кальций не амфотерен и гидроксокомплексов со щёлочью не образует."]], "why": "Справа Ca(OH)2 («М») выпадает в осадок и в ПИУ/СИУ остаётся в молекулярной форме."}, {"id": "rx03_bacl2_na2so4", "sk": "rio_conditions", "ref": "03.10", "n": 30, "lvl": 1, "l": ["BaCl2", "Na2SO4"], "r": ["BaSO4", "NaCl"], "c": [1, 1, 1, 2], "if": "выпадение белого осадка, нерастворимого в кислотах (СИУ: Ba^{2+} + SO4^{2−} → BaSO4↓)", "bad": [["BaSO3", "Степень окисления серы в РИО не меняется — выпадает сульфат BaSO4↓."], ["Na2BaCl4", "Двойной комплекс не образуется, идёт обычный обмен с осадком BaSO4↓."]], "why": "Обе исходные соли имеют статус «Р», продукт BaSO4 — «Н»."}, {"id": "rx04_na2co3_hcl", "sk": "rio_conditions", "ref": "03.13", "n": 30, "lvl": 1, "l": ["Na2CO3", "HCl"], "r": ["NaCl", "CO2", "H2O"], "c": [1, 2, 2, 1, 1], "if": "выделение газа без запаха CO2↑ (СИУ: CO3^{2−} + 2H^{+} → CO2↑ + H2O)", "bad": [["H2CO3", "Угольная кислота неустойчива и в уравнениях РИО всегда пишется как CO2↑ + H2O."], ["CO", "В РИО степень окисления углерода (+4) не меняется — выделяется CO2↑."]], "why": "Неустойчивая H2CO3 мгновенно распадается на CO2↑ + H2O."}, {"id": "rx05_nh4cl_naoh", "sk": "rio_conditions", "ref": "03.14", "n": 30, "lvl": 2, "l": ["NH4Cl", "NaOH"], "r": ["NaCl", "NH3", "H2O"], "c": [1, 1, 1, 1, 1], "if": "t°, выделение газа с резким запахом NH3↑ (СИУ: NH4^{+} + OH^{−} → NH3↑ + H2O)", "bad": [["NH4OH", "Формула NH4OH запрещена на ЕГЭ! При нагревании пишем NH3↑ + H2O, на холоду — NH3·H2O."], ["N2", "Это РИО без изменения СО азота (−3), свободный азот не выделяется."]], "why": "Качественная реакция на катион аммония NH4^{+} в № 6 и № 30."}, {"id": "rx06_kno2_h2so4_demo", "sk": "rio_conditions", "ref": "03.19", "n": 30, "lvl": 3, "l": ["KNO2", "H2SO4"], "r": ["HNO2", "K2SO4"], "c": [2, 1, 2, 1], "if": "разб. р-р без нагрева [ДЕМО-2027]: слабый электролит без газа (СИУ: H^{+} + NO2^{−} → HNO2)", "bad": [["NO2", "В разбавленном растворе без нагревания HNO2 остаётся в растворе без выделения газа."], ["HNO3", "Степень окисления азота (+3) в РИО не меняется — образуется HNO2."]], "why": "Эталон Демоверсии ФИПИ ЕГЭ-2027: в СИУ обязательно сократить двойки (H^{+} + NO2^{−} → HNO2)."}, {"id": "rx07_aloh3_hcl", "sk": "rio_conditions", "ref": "03.25", "n": 30, "lvl": 1, "l": ["Al(OH)3", "HCl"], "r": ["AlCl3", "H2O"], "c": [1, 3, 1, 3], "if": "растворение белого осадка в сильной кислоте (СИУ: Al(OH)3 + 3H^{+} → Al^{3+} + 3H2O)", "bad": [["H2", "Гидроксид алюминия реагирует с кислотой по обмену без выделения водорода."], ["Al(OH)2Cl", "В избытке сильной кислоты образуется средняя растворимая соль AlCl3."]], "why": "Исходный осадок Al(OH)3 в ПИУ и СИУ на ионы не расписывается."}, {"id": "rx08_aloh3_naoh", "sk": "rio_conditions", "ref": "03.26", "n": 30, "lvl": 2, "l": ["Al(OH)3", "NaOH"], "r": ["Na[Al(OH)4]"], "c": [1, 1, 1], "if": "водный раствор щёлочи (СИУ: Al(OH)3 + OH^{−} → [Al(OH)4]^{−})", "bad": [["NaAlO2", "Метаалюминат NaAlO2 образуется при сплавлении, а в водном растворе — гидроксокомплекс Na[Al(OH)4]."], ["Al(ONa)3", "В водной щёлочи алюминий образует комплексный анион [Al(OH)4]^{−}."]], "why": "Комплексный анион [Al(OH)4]^{−} в ПИУ никогда не разбивается на Al^{3+} и OH^{−}."}, {"id": "rx09_znoh2_koh", "sk": "kim6_tubes", "ref": "06.11", "n": 6, "lvl": 2, "l": ["Zn(OH)2", "KOH"], "r": ["K2[Zn(OH)4]"], "c": [1, 2, 1], "if": "растворение амфотерного осадка в водной щёлочи (СИУ: Zn(OH)2 + 2OH^{−} → [Zn(OH)4]^{2−})", "bad": [["K2ZnO2", "Цинкат K2ZnO2 образуется при сплавлении, а в водном растворе — K2[Zn(OH)4]."], ["K[Zn(OH)3]", "В ЕГЭ для цинка в водной щёлочи принят тетрагидроксоцинкат [Zn(OH)4]^{2−}."]], "why": "Классика задания № 6: амфотерный Zn(OH)2 растворяется и в кислоте, и в щёлочи."}, {"id": "rx10_naaloh4_hcl_def", "sk": "rio_conditions", "ref": "03.29", "n": 30, "lvl": 3, "l": ["Na[Al(OH)4]", "HCl"], "r": ["Al(OH)3", "NaCl", "H2O"], "c": [1, 1, 1, 1, 1], "if": "недостаток кислоты (1:1) — выпадение осадка (СИУ: [Al(OH)4]^{−} + H^{+} → Al(OH)3↓ + H2O)", "bad": [["AlCl3", "При соотношении 1:1 (недостаток HCl) комплекс разрушается только до осадка Al(OH)3↓."], ["NaOH", "Щёлочь не может выделиться в присутствии сильной кислоты HCl."]], "why": "Частый сюжет № 30 и № 6: осаждение Al(OH)3↓ из гидроксокомплекса недостатком кислоты."}, {"id": "rx11_naaloh4_hcl_exc", "sk": "rio_conditions", "ref": "03.30", "n": 30, "lvl": 3, "l": ["Na[Al(OH)4]", "HCl"], "r": ["AlCl3", "NaCl", "H2O"], "c": [1, 4, 1, 1, 4], "if": "избыток сильной кислоты (1:4) — без осадка (СИУ: [Al(OH)4]^{−} + 4H^{+} → Al^{3+} + 4H2O)", "bad": [["Al(OH)3", "В избытке сильной HCl осадок Al(OH)3 полностью растворяется до AlCl3."], ["Al2O3", "В водном растворе образуются растворимые хлориды и вода."]], "why": "Четыре протона H^{+} связывают все четыре группы OH^{−} комплексного аниона в 4H2O."}, {"id": "rx12_na2sio3_hcl", "sk": "rio_conditions", "ref": "03.33", "n": 6, "lvl": 2, "l": ["Na2SiO3", "HCl"], "r": ["H2SiO3", "NaCl"], "c": [1, 2, 1, 2], "if": "выпадение белого студенистого осадка кислоты (СИУ: SiO3^{2−} + 2H^{+} → H2SiO3↓)", "bad": [["SiO2", "В водном растворе на холоду выпадает именно кремниевая кислота H2SiO3↓."], ["SiH4", "Степень окисления кремния (+4) в РИО не меняется."]], "why": "H2SiO3 — единственная нерастворимая кислота в школьной таблице ФИПИ."}, {"id": "rx13_agno3_naoh", "sk": "rio_conditions", "ref": "03.33", "n": 30, "lvl": 3, "l": ["AgNO3", "NaOH"], "r": ["Ag2O", "H2O", "NaNO3"], "c": [2, 2, 1, 1, 2], "if": "прочерк у AgOH в таблице ФИПИ (СИУ: 2Ag^{+} + 2OH^{−} → Ag2O↓ + H2O)", "bad": [["AgOH", "Гидроксид серебра AgOH не существует и мгновенно разлагается на Ag2O↓ + H2O."], ["Ag", "Серебро не восстанавливается щёлочью — это РИО без изменения СО."]], "why": "Аналогично ведёт себя Hg(NO3)2 + 2NaOH → HgO↓ + H2O + 2NaNO3."}, {"id": "rx14_nahco3_naoh", "sk": "acid_salts_rio", "ref": "04.14", "n": 30, "lvl": 1, "l": ["NaHCO3", "NaOH"], "r": ["Na2CO3", "H2O"], "c": [1, 1, 1, 1], "if": "без видимых признаков — нейтрализация кислой соли (СИУ: HCO3^{−} + OH^{−} → CO3^{2−} + H2O)", "bad": [["CO2", "Щёлочь переводит кислую соль в среднюю без выделения газа (газ даёт кислота)."], ["Na2O", "В водном растворе образуются Na2CO3 и H2O."]], "why": "Эталон реакции «без видимых признаков» с кислой солью в № 6 и № 30."}, {"id": "rx15_cahco32_caoh2", "sk": "acid_salts_rio", "ref": "04.16", "n": 30, "lvl": 2, "l": ["Ca(HCO3)2", "Ca(OH)2"], "r": ["CaCO3", "H2O"], "c": [1, 1, 2, 2], "if": "выпадение белого осадка (СИУ после сокращения на 2: Ca^{2+} + HCO3^{−} + OH^{−} → CaCO3↓ + H2O)", "bad": [["CO2", "Со щёлочью Ca(OH)2 выделяется не газ, а осадок средней соли CaCO3↓."], ["CaO", "В воде образуется нерастворимый карбонат CaCO3↓ и вода."]], "why": "В СИУ не забудь сократить все коэффициенты на 2!"}, {"id": "rx16_baoh2_nahco3_1_1", "sk": "acid_salts_rio", "ref": "04.20", "n": 30, "lvl": 3, "l": ["Ba(OH)2", "NaHCO3"], "r": ["BaCO3", "NaOH", "H2O"], "c": [1, 1, 1, 1, 1], "if": "1:1 (избыток Ba(OH)2) — осадок и щёлочь (СИУ: Ba^{2+} + OH^{−} + HCO3^{−} → BaCO3↓ + H2O)", "bad": [["Na2CO3", "В избытке Ba(OH)2 весь CO3^{2−} уходит в осадок BaCO3↓, а в растворе остаётся щёлочь NaOH."], ["CO2", "В щелочной среде CO2 не выделяется."]], "why": "Ключевое условие в № 30: «образование осадка и щёлочи» или «образование только одной соли»."}, {"id": "rx17_baoh2_nahco3_1_2", "sk": "acid_salts_rio", "ref": "04.21", "n": 30, "lvl": 3, "l": ["Ba(OH)2", "NaHCO3"], "r": ["BaCO3", "Na2CO3", "H2O"], "c": [1, 2, 1, 1, 2], "if": "1:2 (избыток NaHCO3) — две соли (СИУ: Ba^{2+} + 2OH^{−} + 2HCO3^{−} → BaCO3↓ + CO3^{2−} + 2H2O)", "bad": [["NaOH", "В избытке кислой соли NaHCO3 свободная щёлочь NaOH не остаётся — образуется Na2CO3."], ["Ba(HCO3)2", "Обе группы OH^{−} нейтрализуют оба HCO3^{−}, давая осадок BaCO3↓ и раствор Na2CO3."]], "why": "В СИУ слева 2OH^{−} и 2HCO3^{−}, справа CO3^{2−} — коэффициенты на 2 не делятся из-за 1 Ba^{2+}."}, {"id": "rx18_nahso4_nahco3", "sk": "acid_salts_rio", "ref": "04.25", "n": 30, "lvl": 3, "l": ["NaHSO4", "NaHCO3"], "r": ["Na2SO4", "CO2", "H2O"], "c": [1, 1, 1, 1, 1], "if": "реакция двух кислых солей с газом (СИУ: HSO4^{−} + HCO3^{−} → SO4^{2−} + CO2↑ + H2O)", "bad": [["Na2CO3", "Гидросульфат действует как сильная кислота и вытесняет CO2↑, а не даёт карбонат."], ["SO2", "Степень окисления серы (+6) не меняется — выделяется только CO2↑."]], "why": "Классика № 30: «реакция между двумя кислыми солями с выделением газа»."}, {"id": "rx19_nahso4_bacl2", "sk": "acid_salts_rio", "ref": "04.26", "n": 30, "lvl": 3, "l": ["NaHSO4", "BaCl2"], "r": ["BaSO4", "NaCl", "HCl"], "c": [1, 1, 1, 1, 1], "if": "каноническое соотношение 1:1 (СИУ: Ba^{2+} + SO4^{2−} → BaSO4↓ или Ba^{2+} + HSO4^{−} → BaSO4↓ + H^{+})", "bad": [["Na2SO4", "При 1:1 лишняя соль Na2SO4 не образуется; избыточное 2:1 в ЕГЭ не используют."], ["Ba(HSO4)2", "Сульфат бария BaSO4↓ настолько нерастворим, что осаждается даже в кислой среде."]], "why": "Оба варианта СИУ верны при условии согласованной записи HSO4^{−} в ПИУ."}, {"id": "rx20_nah2po4_na3po4", "sk": "acid_salts_rio", "ref": "04.30", "n": 30, "lvl": 3, "l": ["NaH2PO4", "Na3PO4"], "r": ["Na2HPO4"], "c": [1, 1, 2], "if": "перераспределение протонов без видимых признаков (СИУ: H2PO4^{−} + PO4^{3−} → 2HPO4^{2−})", "bad": [["H3PO4", "Протон переходит от более кислого H2PO4^{−} к более основному PO4^{3−}, давая промежуточную соль."], ["NaOH", "Образуется одна промежуточная кислая соль Na2HPO4."]], "why": "Полноценная РИО «без видимых признаков» с образованием новой кислой соли."}, {"id": "rx21_alcl3_na2co3", "sk": "joint_hydrolysis_30", "ref": "05.5", "n": 30, "lvl": 3, "l": ["AlCl3", "Na2CO3", "H2O"], "r": ["Al(OH)3", "CO2", "NaCl"], "c": [2, 3, 3, 2, 3, 6], "if": "совместный гидролиз: белый осадок + газ без запаха (СИУ: 2Al^{3+} + 3CO3^{2−} + 3H2O → 2Al(OH)3↓ + 3CO2↑)", "bad": [["Al2(CO3)3", "Карбонат алюминия в воде не существует («–» в таблице ФИПИ) — идёт совместный гидролиз."], ["Na[Al(OH)4]", "Раствор Na2CO3 недостаточно щелочной для растворения Al(OH)3 в комплекс."]], "why": "Слева обязательно 3H2O; проверь баланс по O: 9 + 3 = 12 и 6 + 6 = 12."}, {"id": "rx22_fecl3_nahco3", "sk": "joint_hydrolysis_30", "ref": "05.6", "n": 30, "lvl": 3, "l": ["FeCl3", "NaHCO3"], "r": ["Fe(OH)3", "CO2", "NaCl"], "c": [1, 3, 1, 3, 3], "if": "совместный гидролиз без воды в уравнении: бурый осадок + газ (СИУ: Fe^{3+} + 3HCO3^{−} → Fe(OH)3↓ + 3CO2↑)", "bad": [["Fe2(CO3)3", "Карбонат железа(III) в воде не существует — выпадает бурый Fe(OH)3↓ и идёт CO2↑."], ["FeCl2", "C^{+4} не восстановитель, поэтому Fe^{+3} не восстанавливается — это РИО, а не ОВР."]], "why": "С гидрокарбонатом вода в уравнении не нужна: 3 H из 3HCO3^{−} ровно идут на Fe(OH)3."}, {"id": "rx23_alcl3_na2s", "sk": "joint_hydrolysis_30", "ref": "05.10", "n": 30, "lvl": 3, "l": ["AlCl3", "Na2S", "H2O"], "r": ["Al(OH)3", "H2S", "NaCl"], "c": [2, 3, 6, 2, 3, 6], "if": "совместный гидролиз: белый осадок + газ с запахом тухлых яиц (СИУ: 2Al^{3+} + 3S^{2−} + 6H2O → 2Al(OH)3↓ + 3H2S↑)", "bad": [["Al2S3", "Сульфид алюминия в воде полностью разлагается на Al(OH)3↓ и H2S↑."], ["S", "Al^{3+} не окислитель (в отличие от Fe^{3+}), поэтому идёт РИО без выделения серы S↓."]], "why": "Ср. с FeCl3 + Na2S, где идёт ОВР с выпадением серы!"}, {"id": "rx24_k2cr2o7_koh", "sk": "joint_hydrolysis_30", "ref": "05.15", "n": 30, "lvl": 3, "l": ["K2Cr2O7", "KOH"], "r": ["K2CrO4", "H2O"], "c": [1, 2, 2, 1], "if": "оранжевый → жёлтый раствор без осадка и газа (СИУ: Cr2O7^{2−} + 2OH^{−} → 2CrO4^{2−} + H2O)", "bad": [["Cr(OH)3", "Степень окисления хрома (+6) не меняется — это РИО, а не восстановление до +3."], ["O2", "Кислород не выделяется, так как восстановителя в системе нет."]], "why": "Любимая ловушка № 30 на «изменение цвета раствора без осадка и газа»."}, {"id": "rx25_k2cro4_h2so4", "sk": "joint_hydrolysis_30", "ref": "05.16", "n": 30, "lvl": 3, "l": ["K2CrO4", "H2SO4"], "r": ["K2Cr2O7", "K2SO4", "H2O"], "c": [2, 1, 1, 1, 1], "if": "жёлтый → оранжевый раствор (СИУ: 2CrO4^{2−} + 2H^{+} → Cr2O7^{2−} + H2O)", "bad": [["Cr2(SO4)3", "Без восстановителя Cr^{+6} не восстанавливается до Cr^{+3}."], ["SO2", "Реакция не является ОВР."]], "why": "В кислой среде хромат переходит в дихромат, в щелочной — дихромат в хромат."}, {"id": "rx26_alcl3_h2o_hydr", "sk": "hydrolysis_4types", "ref": "07.10", "n": 21, "lvl": 2, "rev": true, "l": ["AlCl3", "H2O"], "r": ["AlOHCl2", "HCl"], "c": [1, 1, 1, 1], "if": "1-я ступень обратимого гидролиза по катиону (среда кислая, pH < 7)", "bad": [["Al(OH)3", "При обычной температуре обратимый гидролиз чистой соли AlCl3 идёт по 1-й ступени без выпадения осадка."], ["Cl2", "Гидролиз — обменная реакция без изменения степеней окисления."]], "why": "Ионное уравнение 1-й ступени: Al^{3+} + H2O ⇄ AlOH^{2+} + H^{+}."}, {"id": "rx27_na2co3_h2o_hydr", "sk": "hydrolysis_4types", "ref": "07.11", "n": 21, "lvl": 2, "rev": true, "l": ["Na2CO3", "H2O"], "r": ["NaHCO3", "NaOH"], "c": [1, 1, 1, 1], "if": "1-я ступень обратимого гидролиза по аниону (среда щелочная, pH > 7)", "bad": [["CO2", "Из чистого раствора Na2CO3 газ CO2 при комнатной температуре не выделяется — гидролиз идёт по 1-й ступени."], ["Na2O", "В воде образуется кислая соль NaHCO3 и щёлочь NaOH."]], "why": "Ионное уравнение 1-й ступени: CO3^{2−} + H2O ⇄ HCO3^{−} + OH^{−}."}, {"id": "rx28_al2s3_h2o", "sk": "hydrolysis_4types", "ref": "07.14", "n": 21, "lvl": 2, "l": ["Al2S3", "H2O"], "r": ["Al(OH)3", "H2S"], "c": [1, 6, 2, 3], "if": "необратимый гидролиз соли 4-го типа (прочерк «–» в таблице ФИПИ)", "bad": [["Al(HS)3", "Сульфид алюминия гидролизуется в воде необратимо до конца — до Al(OH)3↓ и H2S↑."], ["SO2", "Степень окисления серы (−2) при гидролизе не меняется."]], "why": "Соль слабого основания и слабой летучей кислоты разлагается водой необратимо."}, {"id": "rx29_alcl3_nh3h2o", "sk": "rio_conditions", "ref": "03.31", "n": 30, "lvl": 2, "l": ["AlCl3", "NH3·H2O"], "r": ["Al(OH)3", "NH4Cl"], "c": [1, 3, 1, 3], "if": "осаждение Al(OH)3 водным аммиаком (в избытке NH3·H2O осадок НЕ растворяется!)", "bad": [["NH4[Al(OH)4]", "В избытке водного аммиака NH3·H2O осадок Al(OH)3 не растворяется и комплекс не образует."], ["Al(NH3)3", "Водный аммиак действует как слабое основание, осаждая Al(OH)3↓."]], "why": "Водный аммиак пишется строго как NH3·H2O (не NH4OH!) и не расписывается в ПИУ."}], "seq": [{"id": "seq_piu_siu", "sk": "fipi_solubility_piu", "ref": "02.17", "n": 30, "lvl": 2, "q": "Выстрой в правильном порядке 5 шагов составления уравнений в задании № 30:", "items": ["Выбрать пару электролитов строго по условию (без ОВР и оксидов) и уравнять молекулярное уравнение (МУ)", "Проверить каждое вещество по таблице ФИПИ и списку 9 сильных кислот: расписать на ионы только сильные растворимые электролиты (ПИУ)", "Вынести индексы свободных ионов вперёд как коэффициенты и проверить формат заряда (цифра перед знаком: Fe^{2+}, SO4^{2−})", "Вычеркнуть одинаковые ионы-наблюдатели слева и справа и переписать сокращённое ионное уравнение (СИУ)", "Сократить общие кратные коэффициенты в СИУ и сверить баланс атомов и суммарного заряда"], "why": "Финальная проверка кратных коэффициентов и заряда в СИУ спасает от потери 2-го балла."}, {"id": "seq_kim30_filter", "sk": "joint_hydrolysis_30", "ref": "05.17", "n": 30, "lvl": 3, "q": "Расположи в правильном порядке 5 шагов фильтрации пары веществ из перечня для задания № 30:", "items": ["Выписать формулы всех 6 веществ перечня и подписать их статус по таблице ФИПИ («Р», «Н», кислота, щёлочь)", "Отсечь пары, вступающие в ОВР (включая скрытые Fe^{3+} + S^{2−}/SO3^{2−}/I^{−} и Cu^{2+} + I^{−})", "Отсечь неэлектролиты (оксиды, простые вещества), реакции твёрдых солей с H2SO4(конц.) и обмен двух солей с нерастворимой солью слева", "Проверить наличие осадка, газа или слабого электролита и точное совпадение с каждым словом условия", "Записать сбалансированную тройку МУ → ПИУ → СИУ"], "why": "Последовательная фильтрация защищает от выбора ОВР или неэлектролита (0 баллов за всё № 30)."}, {"id": "seq_ph_floors", "sk": "ph_scale_acid_salts", "ref": "08.8", "n": 21, "lvl": 2, "q": "Расположи 5 типов водных растворов одинаковой молярной концентрации в порядке ВОЗРАСТАНИЯ pH (от кислого к щелочному):", "items": ["Сильная кислота (HCl, HNO3, H2SO4)", "Слабая кислота (CH3COOH, HF, H3PO4)", "Соль гидролиза по катиону (NH4Cl, AlCl3, Fe(NO3)3)", "Нейтральная соль или неэлектролит (NaCl, K2SO4, C2H5OH)", "Сильная щёлочь (NaOH, KOH, Ba(OH)2)"], "why": "Чем ниже pH, тем выше кислотность; возрастание pH идёт от сильной кислоты к сильной щёлочи."}, {"id": "seq_phosphates_ph", "sk": "kim21_ranking", "ref": "09.15", "n": 21, "lvl": 3, "q": "Расположи водные растворы фосфатов одинаковой молярной концентрации в порядке ВОЗРАСТАНИЯ pH:", "items": ["H3PO4 (кислота средней силы)", "NaH2PO4 (кислая соль со слабокислой средой, pH < 7)", "Na2HPO4 (кислая соль со слабощелочной средой, pH > 7)", "Na3PO4 (средняя соль слабой кислоты, сильнощелочная среда)"], "why": "Классический ряд № 21: NaH2PO4 стоит по кислую сторону от 7, а Na2HPO4 — уже по щелочную."}], "facts": [{"id": "f_electrolytes", "sk": "electrolytes", "ref": "01.19", "n": 30, "lvl": 2, "t": "Сильные и слабые электролиты, степень диссоциации α", "s": [["Все растворимые в воде соли («Р» в таблице ФИПИ) являются сильными электролитами, даже если образованы слабой кислотой.", "Растворимые соли слабых кислот (CH3COONa, Na2CO3) являются слабыми электролитами.", "В кристалле соли связь ионная, поэтому в воде соль распадается на ионы полностью."], ["Фосфорная (H3PO4), фтороводородная (HF) и азотистая (HNO2) кислоты в ПИУ на ионы не расписываются.", "H3PO4, HF и HNO2 входят в список сильных кислот ЕГЭ и расписываются на ионы.", "В список 9 сильных кислот входят только HCl, HBr, HI, HNO3, H2SO4, HClO4, HClO3, HMnO4, H2Cr2O7."], ["При разбавлении водного раствора уксусной кислоты CH3COOH водой степень её диссоциации α увеличивается.", "При разбавлении водного раствора CH3COOH водой степень диссоциации α уменьшается.", "При разбавлении ионам сложнее встретиться и снова соединиться в молекулу."], ["Оксиды (SO3, CO2, CaO), металлы (Fe) и спирты (C2H5OH) не являются электролитами.", "Оксид серы(VI) SO3 и металлический натрий относятся к сильным электролитам.", "Металлы проводят ток за счёт электронов, а не ионов; оксиды не диссоциируют на ионы."], ["Многоосновная слабая кислота H3PO4 диссоциирует ступенчато, преимущественно по первой ступени.", "Фосфорная кислота H3PO4 в воде сразу распадается на 3H^{+} и PO4^{3−}.", "Оторвать протон от нейтральной H3PO4 гораздо легче, чем от уже отрицательного аниона H2PO4^{−}."]]}, {"id": "f_fipi_rules", "sk": "fipi_solubility_piu", "ref": "02.17", "n": 30, "lvl": 3, "t": "Таблица ФИПИ-2027 и 5 правил оформления № 30", "s": [["Малорастворимые щёлочи Ca(OH)2 и Sr(OH)2 расписываются на ионы слева (в растворе), но пишутся молекулой справа (в осадке).", "Гидроксид кальция Ca(OH)2 всегда пишется молекулой и слева, и справа.", "Это позиционное правило ФИПИ: известковая вода слева — раствор сильной щёлочи, а справа — осадок."], ["Малорастворимые соли (CaSO4, Ag2SO4, PbCl2, LiF) не расписываются на ионы ни слева, ни справа.", "Малорастворимую соль CaSO4 слева расписывают на ионы так же, как Ca(OH)2.", "Позиционное исключение действует только для двух малорастворимых щелочей Ca(OH)2 и Sr(OH)2."], ["В официальной таблице ФИПИ-2027 у Ca(CH3COO)2, Ba(HCO3)2 и (NH4)3PO4 стоит прочерк «–», поэтому их не выбирают слева в № 30.", "В таблице ФИПИ-2027 у всех ацетатов и всех гидрокарбонатов стоит пометка «Р».", "У Ca(CH3COO)2, Ba/Mg/Sr(HCO3)2 и (NH4)3PO4 в бланке ФИПИ стоит «–»."], ["Заряд иона в ПИУ и СИУ пишется цифрой перед знаком (Fe^{3+}, SO4^{2−}), а запись Fe^{+3} считается ошибкой.", "В ПИУ и СИУ допускается писать заряд иона как Fe^{+3} или Fe^{3+} на выбор.", "Знак перед цифрой — это степень окисления, а не заряд иона; в № 30 за подмену снимают балл."], ["Вместо формулы NH4OH на ЕГЭ всегда пишут NH3·H2O (без выделения газа) или NH3↑ + H2O (при выделении газа).", "В реакциях солей аммония со щёлочью без нагревания в № 30 следует писать молекулу NH4OH.", "Молекула NH4OH не существует и запрещена критериями ФИПИ."]]}, {"id": "f_acid_salts", "sk": "acid_salts_rio", "ref": "04.7", "n": 30, "lvl": 3, "t": "Кислые соли и псевдокислые соли в № 30", "s": [["В ПИУ кислые анионы слабых кислот (HCO3^{−}, HSO3^{−}, HS^{−}, H2PO4^{−}, HPO4^{2−}) запрещено расписывать на H^{+}.", "В ПИУ кислую соль NaHCO3 нужно расписывать как Na^{+} + H^{+} + CO3^{2−}.", "Вторая ступень диссоциации слабых кислот идёт ничтожно слабо — кислый анион остаётся целым."], ["Для гидросульфат-иона HSO4^{−} ФИПИ допускает оба варианта записи в ПИУ, но строго согласованно слева и справа.", "Ион HSO4^{−} можно оставить целым слева, а справа записать SO4^{2−} без переноса протона.", "Нарушение согласованности сторон ломает баланс атомов водорода и зарядов."], ["Реакция Ba(OH)2 + NaHCO3 в соотношении 1:1 даёт осадок BaCO3↓ и щёлочь NaOH.", "Реакция Ba(OH)2 + NaHCO3 при любом соотношении даёт только BaCO3↓ и Na2CO3.", "В избытке Ba(OH)2 (1:1) остаётся свободный OH^{−} → образуется щёлочь NaOH."], ["Фосфит натрия Na2HPO3 и гипофосфит натрия NaH2PO2 — средние соли и не вступают в нейтрализацию со щёлочью.", "Na2HPO3 и NaH2PO2 — кислые соли, которые легко нейтрализуются NaOH до Na3PO3 и Na3PO2.", "H3PO3 двухосновна, H3PO2 одноосновна — оставшиеся атомы H связаны с фосфором и не замещаются."], ["Смешивание растворов NaH2PO4 и Na3PO4 — полноценная РИО с образованием Na2HPO4 (СИУ: H2PO4^{−} + PO4^{3−} → 2HPO4^{2−}).", "Две растворимые соли одной кислоты (NaH2PO4 и Na3PO4) между собой не реагируют.", "Происходит перенос протона от донора H2PO4^{−} к акцептору PO4^{3−}."]]}, {"id": "f_joint_and_limits", "sk": "joint_hydrolysis_30", "ref": "05.13", "n": 30, "lvl": 3, "t": "Совместный гидролиз и границы задания № 30", "s": [["Пары FeCl3 + Na2CO3 и FeCl3 + NaHCO3 являются РИО (совместный гидролиз) и подходят для № 30.", "Любая реакция с FeCl3 и прочерком в таблице ФИПИ является ОВР и запрещена в № 30.", "Углерод в CO3^{2−}/HCO3^{−} имеет высшую СО (+4) и не может окисляться ионом Fe^{3+}."], ["Пары FeCl3 + Na2S, FeCl3 + Na2SO3, FeCl3 + KI и CuSO4 + KI — это скрытые ОВР, запрещённые в № 30.", "Реакция FeCl3 + Na2S — это совместный гидролиз с образованием Fe(OH)3↓ и H2S↑.", "Ионы Fe^{3+} и Cu^{2+} окисляют восстановители S^{2−}, SO3^{2−}, I^{−} с изменением степеней окисления."], ["Переход дихромата калия в хромат со щёлочью (K2Cr2O7 + 2KOH → 2K2CrO4 + H2O) является РИО и разрешён в № 30.", "Любая реакция с участием K2Cr2O7 является ОВР и запрещена в № 30.", "Степень окисления хрома (+6) в Cr2O7^{2−} и CrO4^{2−} одинакова."], ["Реакции с оксидами (CaO + HCl) и твёрдых солей с концентрированной H2SO4 запрещено записывать в № 30.", "Реакцию NaCl(тв.) + H2SO4(конц.) → NaHSO4 + HCl↑ можно записать в № 30 на выделение газа.", "В № 30 требуются только реакции ионного обмена между электролитами в водном растворе."], ["Если в № 30 выбрана пара, не соответствующая условию (например, с газом вместо «без газа»), за всё задание ставят 0 баллов.", "Если в № 30 перепутать условие, но верно написать ПИУ и СИУ к своей реакции, поставят 1 балл из 2.", "Первый критерий № 30 — верный выбор веществ по условию; при 0 за 1-й критерий 2-й не засчитывается."]]}, {"id": "f_kim6_traps", "sk": "kim6_tubes", "ref": "06.18", "n": 6, "lvl": 2, "t": "Ловушки пробирок X и Y в задании № 6", "s": [["Для полного растворения осадка BaCO3 в кислоте выбирают HCl или HNO3, но не H2SO4.", "Серная кислота H2SO4 полностью растворяет осадок BaCO3 с образованием прозрачного раствора.", "С H2SO4 на смену BaCO3↓ сразу выпадает новый нерастворимый осадок BaSO4↓."], ["Осадок Al(OH)3 растворяется в избытке водного NaOH, но не растворяется в избытке водного аммиака NH3·H2O.", "Осадок Al(OH)3 легко растворяется в избытке водного аммиака NH3·H2O.", "NH3·H2O — слишком слабое основание, а аммиачных комплексов алюминий не образует."], ["Сульфид железа(II) FeS растворяется в разбавленной HCl с выделением H2S↑, а CuS и Ag2S — нет.", "Все чёрные сульфиды (FeS, CuS, Ag2S) одинаково легко растворяются в разбавленной HCl.", "CuS, PbS, Ag2S и HgS не растворяются в разбавленных неокисляющих кислотах."], ["Голубой Cu(OH)2 и бурый Fe(OH)3 не растворяются в водном растворе KOH, в отличие от серо-зелёного Cr(OH)3.", "Гидроксид железа(III) Fe(OH)3 легко растворяется в водном растворе NaOH с образованием комплекса.", "В ЕГЭ Fe(OH)3 в водных растворах щелочей не растворяется (только при сплавлении)."], ["В задании № 6 перестановка цифр X и Y местами обнуляет все 2 балла.", "В задании № 6 за перестановку X и Y местами снимают только 1 балл из 2.", "Каждая позиция проверяется отдельно: при перестановке не совпадают обе позиции (0/2)."]]}, {"id": "f_hydrolysis_ph", "sk": "ph_scale_acid_salts", "ref": "08.16", "n": 21, "lvl": 3, "t": "Гидролиз, кислые соли и органика в № 21", "s": [["Водные растворы солей магния (MgCl2, MgSO4) имеют кислую среду, а солей кальция и бария (CaCl2, Ba(NO3)2) — нейтральную.", "Соли магния, кальция и бария с сильными кислотами одинаково не гидролизуются (pH = 7).", "Mg(OH)2 — слабое нерастворимое основание, а Ca(OH)2 и Ba(OH)2 — сильные щёлочи."], ["Из 6 кислых солей NaHSO4, NaH2PO4 и NaHSO3 дают кислую среду, а NaHCO3, Na2HPO4 и NaHS — слабощелочную.", "Все кислые соли в воде дают кислую среду (pH < 7), так как содержат водород в анионе.", "У HCO3^{−}, HPO4^{2−} и HS^{−} константа гидролиза больше константы диссоциации."], ["При одинаковой молярной концентрации pH(H2SO4) ниже, чем pH(HCl), а pH(Ba(OH)2) выше, чем pH(NaOH).", "При одинаковой молярной концентрации все сильные кислоты имеют строго одинаковый pH.", "H2SO4 двухосновна (даёт больше H^{+}), Ba(OH)2 двухкислотен (даёт больше OH^{−})."], ["Водный раствор анилина C6H5NH2 имеет почти нейтральную среду (pH ≈ 7), а метиламина CH3NH2 — слабощелочную (pH > 7).", "Анилин C6H5NH2 — более сильное основание, чем метиламин, и окрашивает фенолфталеин в малиновый цвет.", "Бензольное кольцо оттягивает электронную пару азота, резко ослабляя основность анилина."], ["Фенолфталеин бесцветен и в кислой, и в нейтральной среде, а малиновым становится только в щелочной.", "Фенолфталеин позволяет отличить кислую среду от нейтральной по смене окраски.", "Для отличия кислой среды от нейтральной используют лакмус или метилоранж."]]}], "calc": [{"id": "c_alpha_percent", "sk": "electrolytes", "ref": "01.16", "n": 30, "lvl": 1, "v": {"_": [{"d": 4, "n": 200}, {"d": 15, "n": 500}, {"d": 6, "n": 300}, {"d": 25, "n": 1000}, {"d": 12, "n": 400}]}, "q": "В водном растворе слабого электролита из {=n} растворённых молекул на ионы распались {=d} молекул(ы). Вычисли степень диссоциации α в процентах (%).", "a": "d / n * 100", "dp": 1, "unit": "%", "ex": "α = (N_дисс / N_общ) · 100% = ({=d} / {=n}) · 100% = {=d/n*100}%."}, {"id": "c_ph_from_oh", "sk": "ph_scale_acid_salts", "ref": "08.4", "n": 21, "lvl": 2, "v": {"_": [{"m": 2}, {"m": 3}, {"m": 4}, {"m": 10}, {"m": 11}, {"m": 12}]}, "q": "При 25 °C в водном растворе концентрация гидроксид-ионов составляет [OH^{−}] = 10^{−{=m}} моль/л. Используя ионное произведение воды Kw = 10⁻¹⁴, вычисли значение pH этого раствора.", "a": "14 - m", "dp": 0, "unit": "", "ex": "[H^{+}] = Kw / [OH^{−}] = 10⁻¹⁴ / 10^{−{=m}} = 10^{−{=14-m}} моль/л → pH = −lg[H^{+}] = {=14-m}."}, {"id": "c_ph_dilution_factor", "sk": "ph_scale_acid_salts", "ref": "08.7", "n": 21, "lvl": 2, "v": {"_": [{"p1": 2, "p2": 4}, {"p1": 3, "p2": 4}, {"p1": 1, "p2": 4}, {"p1": 2, "p2": 5}]}, "q": "При разбавлении кислого раствора его pH вырос с {=p1} до {=p2}. Во сколько раз при этом УМЕНЬШИЛАСЬ концентрация ионов водорода [H^{+}]?", "a": "10 ^ (p2 - p1)", "dp": 0, "unit": "раз", "ex": "Каждая единица pH соответствует изменению [H^{+}] в 10 раз: ΔpH = {=p2} − {=p1} = {=p2-p1} → концентрация уменьшилась в 10^{=p2-p1} = {=10^(p2-p1)} раз."}], "tasks": [{"id": "t01_eqn_nahco3_diss", "type": "eqn", "sk": "acid_salts_rio", "ref": "04.4", "n": 30, "lvl": 1, "q": "Запиши уравнение диссоциации гидрокарбоната натрия NaHCO3 в водном растворе так, как его нужно расписывать в ПИУ (кислый анион не разбивай!).", "a": "NaHCO3 → Na^{+} + HCO3^{−}", "ex": "Растворимая кислая соль слабой кислоты диссоциирует на катион металла и целый кислый анион: NaHCO3 → Na^{+} + HCO3^{−}."}, {"id": "t02_eqn_nah2po4_diss", "type": "eqn", "sk": "acid_salts_rio", "ref": "04.4", "n": 30, "lvl": 1, "q": "Запиши уравнение диссоциации дигидрофосфата натрия NaH2PO4 в водном растворе для записи в ПИУ.", "a": "NaH2PO4 → Na^{+} + H2PO4^{−}", "ex": "Кислый анион H2PO4^{−} (как и HCO3^{−}, HSO3^{−}, HS^{−}, HPO4^{2−}) в ПИУ пишется единым ионом: NaH2PO4 → Na^{+} + H2PO4^{−}."}, {"id": "t03_eqn_siu_demo2027", "type": "eqn", "sk": "rio_conditions", "ref": "03.19", "n": 30, "lvl": 2, "q": "Запиши сокращённое ионное уравнение (СИУ) реакции из Демоверсии-2027: 2KNO2 + H2SO4(разб.) → 2HNO2 + K2SO4 (не забудь сократить коэффициенты!).", "a": "H^{+} + NO2^{−} → HNO2", "ex": "В ПИУ двойки стоят перед всеми частицами: 2H^{+} + 2NO2^{−} → 2HNO2. После обязательного сокращения на 2 получаем H^{+} + NO2^{−} → HNO2."}, {"id": "t04_eqn_siu_baoh2_nahco3", "type": "eqn", "sk": "acid_salts_rio", "ref": "04.20", "n": 30, "lvl": 3, "q": "Запиши сокращённое ионное уравнение (СИУ) реакции Ba(OH)2 + NaHCO3 → BaCO3 + NaOH + H2O (соотношение 1:1, избыток щёлочи).", "a": "Ba^{2+} + OH^{−} + HCO3^{−} → BaCO3 + H2O", "ex": "Один из двух OH^{−} слева сокращается с OH^{−} из NaOH справа: Ba^{2+} + OH^{−} + HCO3^{−} → BaCO3↓ + H2O."}, {"id": "t05_eqn_siu_fecl3_nahco3", "type": "eqn", "sk": "joint_hydrolysis_30", "ref": "05.6", "n": 30, "lvl": 3, "q": "Запиши сокращённое ионное уравнение (СИУ) совместного гидролиза FeCl3 + 3NaHCO3 → Fe(OH)3 + 3CO2 + 3NaCl.", "a": "Fe^{3+} + 3HCO3^{−} → Fe(OH)3 + 3CO2", "ex": "Ионы Na^{+} и Cl^{−} сокращаются, вода не требуется: Fe^{3+} + 3HCO3^{−} → Fe(OH)3↓ + 3CO2↑."}, {"id": "t05a_eqn_h3po4_step1", "type": "eqn", "sk": "electrolytes", "ref": "01.25", "n": 30, "lvl": 1, "q": "Запиши уравнение 1-й (основной) ступени обратимой диссоциации фосфорной кислоты H3PO4.", "a": "H3PO4 ⇄ H^{+} + H2PO4^{−}", "ex": "По 1-й ступени от нейтральной молекулы H3PO4 отщепляется один протон H^{+} с образованием дигидрофосфат-иона H2PO4^{−}."}, {"id": "t05b_eqn_h3po4_step2", "type": "eqn", "sk": "electrolytes", "ref": "01.25", "n": 30, "lvl": 2, "q": "Запиши уравнение 2-й ступени обратимой диссоциации фосфорной кислоты (отщепление протона от H2PO4^{−}).", "a": "H2PO4^{−} ⇄ H^{+} + HPO4^{2−}", "ex": "Дигидрофосфат-ион H2PO4^{−} отщепляет второй протон H^{+}, превращаясь в гидрофосфат-ион HPO4^{2−}."}, {"id": "t05c_eqn_h3po4_step3", "type": "eqn", "sk": "electrolytes", "ref": "01.25", "n": 30, "lvl": 2, "q": "Запиши уравнение 3-й ступени обратимой диссоциации фосфорной кислоты (отщепление протона от HPO4^{2−}).", "a": "HPO4^{2−} ⇄ H^{+} + PO4^{3−}", "ex": "Третья ступень идёт крайне слабо: HPO4^{2−} ⇄ H^{+} + PO4^{3−}."}, {"id": "t05d_eqn_siu_neutral", "type": "eqn", "sk": "fipi_solubility_piu", "ref": "02.13", "n": 30, "lvl": 1, "q": "Запиши сокращённое ионное уравнение (СИУ) реакции Ca(OH)2 + 2HCl → CaCl2 + 2H2O (не забудь сократить двойки!).", "a": "H^{+} + OH^{−} → H2O", "ex": "Известковая вода Ca(OH)2 слева расписывается на ионы; после сокращения на 2 получаем H^{+} + OH^{−} → H2O."}, {"id": "t05e_eqn_siu_caoh2_ppt", "type": "eqn", "sk": "fipi_solubility_piu", "ref": "02.14", "n": 30, "lvl": 2, "q": "Запиши СИУ реакции CaCl2 + 2NaOH → Ca(OH)2↓ + 2NaCl (справа Ca(OH)2 — осадок!).", "a": "Ca^{2+} + 2OH^{−} → Ca(OH)2", "ex": "По позиционному правилу ФИПИ малорастворимая щёлочь Ca(OH)2 справа пишется молекулой."}, {"id": "t05f_eqn_siu_baso4", "type": "eqn", "sk": "rio_conditions", "ref": "03.10", "n": 30, "lvl": 1, "q": "Запиши СИУ реакции BaCl2 + Na2SO4 → BaSO4↓ + 2NaCl.", "a": "Ba^{2+} + SO4^{2−} → BaSO4", "ex": "Ионы Na^{+} и Cl^{−} — наблюдатели; связываются только Ba^{2+} и SO4^{2−}."}, {"id": "t05g_eqn_siu_co2", "type": "eqn", "sk": "rio_conditions", "ref": "03.13", "n": 30, "lvl": 1, "q": "Запиши СИУ реакции Na2CO3 + 2HCl → 2NaCl + CO2↑ + H2O.", "a": "CO3^{2−} + 2H^{+} → CO2 + H2O", "ex": "Неустойчивая угольная кислота сразу пишется как CO2↑ + H2O."}, {"id": "t05h_eqn_siu_nh3", "type": "eqn", "sk": "rio_conditions", "ref": "03.14", "n": 30, "lvl": 2, "q": "Запиши СИУ реакции NH4Cl + NaOH —t°→ NaCl + NH3↑ + H2O (при нагревании, с выделением газа).", "a": "NH4^{+} + OH^{−} → NH3 + H2O", "ex": "При нагревании выделяется газ NH3↑ и вода H2O (формула NH4OH запрещена!)."}, {"id": "t05i_eqn_siu_aloh3_acid", "type": "eqn", "sk": "rio_conditions", "ref": "03.25", "n": 30, "lvl": 2, "q": "Запиши СИУ растворения осадка Al(OH)3 в соляной кислоте: Al(OH)3 + 3HCl → AlCl3 + 3H2O.", "a": "Al(OH)3 + 3H^{+} → Al^{3+} + 3H2O", "ex": "Исходный осадок Al(OH)3 слева на ионы не расписывается."}, {"id": "t05j_eqn_siu_aloh3_alkali", "type": "eqn", "sk": "rio_conditions", "ref": "03.26", "n": 30, "lvl": 2, "q": "Запиши СИУ растворения осадка Al(OH)3 в избытке NaOH: Al(OH)3 + NaOH → Na[Al(OH)4].", "a": "Al(OH)3 + OH^{−} → [Al(OH)4]^{−}", "ex": "Комплексный анион [Al(OH)4]^{−} пишется целиком без разбивания квадратных скобок."}, {"id": "t05k_eqn_siu_complex_def", "type": "eqn", "sk": "rio_conditions", "ref": "03.29", "n": 30, "lvl": 3, "q": "Запиши СИУ разрушения комплекса недостатком кислоты: Na[Al(OH)4] + HCl → Al(OH)3↓ + NaCl + H2O.", "a": "[Al(OH)4]^{−} + H^{+} → Al(OH)3 + H2O", "ex": "Один протон H^{+} отщепляет одну группу OH^{−} от комплекса, осаждая Al(OH)3↓."}, {"id": "t05l_eqn_siu_complex_exc", "type": "eqn", "sk": "rio_conditions", "ref": "03.30", "n": 30, "lvl": 3, "q": "Запиши СИУ полного растворения комплекса в избытке кислоты: Na[Al(OH)4] + 4HCl → AlCl3 + NaCl + 4H2O.", "a": "[Al(OH)4]^{−} + 4H^{+} → Al^{3+} + 4H2O", "ex": "Четыре протона H^{+} переводят комплекс в катион Al^{3+} и 4H2O."}, {"id": "t05m_eqn_siu_alcl3_nh3", "type": "eqn", "sk": "rio_conditions", "ref": "03.31", "n": 30, "lvl": 2, "q": "Запиши СИУ осаждения Al(OH)3 водным аммиаком: AlCl3 + 3NH3·H2O → Al(OH)3↓ + 3NH4Cl.", "a": "Al^{3+} + 3NH3·H2O → Al(OH)3 + 3NH4^{+}", "ex": "Водный аммиак NH3·H2O — слабый электролит, в ПИУ и СИУ остаётся молекулой."}, {"id": "t05n_eqn_siu_nahco3_naoh", "type": "eqn", "sk": "acid_salts_rio", "ref": "04.14", "n": 30, "lvl": 2, "q": "Запиши СИУ реакции NaHCO3 + NaOH → Na2CO3 + H2O.", "a": "HCO3^{−} + OH^{−} → CO3^{2−} + H2O", "ex": "Кислый анион HCO3^{−} не расписывается на H^{+}; щёлочь переводит его в CO3^{2−} + H2O."}, {"id": "t05o_eqn_siu_cahco32_caoh2", "type": "eqn", "sk": "acid_salts_rio", "ref": "04.16", "n": 30, "lvl": 2, "q": "Запиши СИУ реакции Ca(HCO3)2 + Ca(OH)2 → 2CaCO3↓ + 2H2O (не забудь сократить на 2!).", "a": "Ca^{2+} + HCO3^{−} + OH^{−} → CaCO3 + H2O", "ex": "В ПИУ все коэффициенты кратны 2, поэтому в СИУ их обязательно сокращают на 2."}, {"id": "t05p_eqn_siu_baoh2_nahco3_1_2", "type": "eqn", "sk": "acid_salts_rio", "ref": "04.21", "n": 30, "lvl": 3, "q": "Запиши СИУ реакции Ba(OH)2 + 2NaHCO3 → BaCO3↓ + Na2CO3 + 2H2O (избыток NaHCO3, 1:2).", "a": "Ba^{2+} + 2OH^{−} + 2HCO3^{−} → BaCO3 + CO3^{2−} + 2H2O", "ex": "Один CO3^{2−} уходит в осадок BaCO3↓, второй остаётся свободным в растворе."}, {"id": "t05q_eqn_siu_nahso4_nahco3", "type": "eqn", "sk": "acid_salts_rio", "ref": "04.25", "n": 30, "lvl": 3, "q": "Запиши СИУ реакции двух кислых солей NaHSO4 + NaHCO3 → Na2SO4 + CO2↑ + H2O (оставляя HSO4^{−} целым).", "a": "HSO4^{−} + HCO3^{−} → SO4^{2−} + CO2 + H2O", "ex": "HSO4^{−} передаёт протон HCO3^{−}, давая SO4^{2−} и распадающуюся H2CO3 (CO2↑ + H2O)."}, {"id": "t05r_eqn_siu_phosphates", "type": "eqn", "sk": "acid_salts_rio", "ref": "04.30", "n": 30, "lvl": 3, "q": "Запиши СИУ перераспределения протонов: NaH2PO4 + Na3PO4 → 2Na2HPO4.", "a": "H2PO4^{−} + PO4^{3−} → 2HPO4^{2−}", "ex": "Заряд слева (−1) + (−3) = −4; справа 2·(−2) = −4."}, {"id": "t05s_eqn_siu_alcl3_na2co3", "type": "eqn", "sk": "joint_hydrolysis_30", "ref": "05.5", "n": 30, "lvl": 3, "q": "Запиши СИУ совместного гидролиза 2AlCl3 + 3Na2CO3 + 3H2O → 2Al(OH)3↓ + 3CO2↑ + 6NaCl.", "a": "2Al^{3+} + 3CO3^{2−} + 3H2O → 2Al(OH)3 + 3CO2", "ex": "Ионы Na^{+} и Cl^{−} сокращаются, 3 молекулы H2O остаются слева."}, {"id": "t05t_eqn_siu_cr2o7_oh", "type": "eqn", "sk": "joint_hydrolysis_30", "ref": "05.15", "n": 30, "lvl": 3, "q": "Запиши СИУ перехода дихромата в хромат в щёлочи: K2Cr2O7 + 2KOH → 2K2CrO4 + H2O.", "a": "Cr2O7^{2−} + 2OH^{−} → 2CrO4^{2−} + H2O", "ex": "Степень окисления хрома (+6) не меняется; баланс зарядов: −4 слева и −4 справа."}, {"id": "t05u_eqn_siu_cro4_h", "type": "eqn", "sk": "joint_hydrolysis_30", "ref": "05.16", "n": 30, "lvl": 3, "q": "Запиши СИУ перехода хромата в дихромат в кислоте: 2K2CrO4 + H2SO4 → K2Cr2O7 + K2SO4 + H2O.", "a": "2CrO4^{2−} + 2H^{+} → Cr2O7^{2−} + H2O", "ex": "Заряд слева 2·(−2) + 2·(+1) = −2; справа −2."}, {"id": "t05v_eqn_hydr_al3", "type": "eqn", "sk": "hydrolysis_4types", "ref": "07.10", "n": 21, "lvl": 2, "q": "Запиши ионное уравнение 1-й ступени обратимого гидролиза солей алюминия (катион Al^{3+}).", "a": "Al^{3+} + H2O ⇄ AlOH^{2+} + H^{+}", "ex": "Катион Al^{3+} связывает один OH^{−} из воды, освобождая H^{+} (кислая среда)."}, {"id": "t05w_eqn_hydr_co3", "type": "eqn", "sk": "hydrolysis_4types", "ref": "07.11", "n": 21, "lvl": 2, "q": "Запиши ионное уравнение 1-й ступени обратимого гидролиза карбонатов (анион CO3^{2−}).", "a": "CO3^{2−} + H2O ⇄ HCO3^{−} + OH^{−}", "ex": "Анион CO3^{2−} забирает один H^{+} у воды, освобождая OH^{−} (щелочная среда)."}, {"id": "t05x_eqn_hydr_nh4", "type": "eqn", "sk": "hydrolysis_4types", "ref": "07.12", "n": 21, "lvl": 2, "q": "Запиши ионное уравнение обратимого гидролиза катиона аммония NH4^{+} в воде (без формулы NH4OH!).", "a": "NH4^{+} + H2O ⇄ NH3·H2O + H^{+}", "ex": "Продукт гидролиза аммония — водный аммиак NH3·H2O и ион водорода H^{+} (кислая среда)."}, {"id": "t05y_eqn_hydr_ch3coo", "type": "eqn", "sk": "hydrolysis_4types", "ref": "07.12", "n": 21, "lvl": 2, "q": "Запиши ионное уравнение обратимого гидролиза ацетат-иона CH3COO^{−} в воде.", "a": "CH3COO^{−} + H2O ⇄ CH3COOH + OH^{−}", "ex": "Образуется слабая уксусная кислота CH3COOH и свободный OH^{−} (щелочная среда)."}, {"id": "t06_kim6_znoh2", "type": "match", "sk": "kim6_tubes", "ref": "06.10", "n": 6, "lvl": 2, "q": "[КИМ № 6] В две пробирки с осадком Zn(OH)2 добавили растворы X и Y. В первой пробирке осадок растворился с образованием соли цинка(II), во второй — с образованием комплексной соли. Определи X и Y.", "left": ["Вещество X (образование соли цинка(II))", "Вещество Y (образование комплексной соли)"], "right": ["NaCl", "KOH", "H2SiO3", "HNO3", "Ba(NO3)2"], "a": [3, 1], "ex": "X = HNO3 (4): Zn(OH)2 + 2HNO3 → Zn(NO3)2 + 2H2O (H2SiO3 нерастворима!). Y = KOH (2): Zn(OH)2 + 2KOH → K2[Zn(OH)4]. Ответ: 42."}, {"id": "t07_kim6_na2co3", "type": "match", "sk": "kim6_tubes", "ref": "06.13", "n": 6, "lvl": 3, "q": "[КИМ № 6] В две пробирки с раствором Na2CO3 добавили растворы X и Y. В первой выпал белый осадок (газ не выделялся), во второй — белый осадок и выделился газ без запаха. Определи X и Y.", "left": ["Вещество X (белый осадок без газа)", "Вещество Y (белый осадок + газ без запаха)"], "right": ["HCl", "Ba(NO3)2", "AlCl3", "K2SO4", "NaOH"], "a": [1, 2], "ex": "X = Ba(NO3)2 (2) → BaCO3↓ без газа. Y = AlCl3 (3) → совместный гидролиз: Al(OH)3↓ + CO2↑ (HCl дал бы только газ без осадка!). Ответ: 23."}, {"id": "t08_kim6_koh", "type": "match", "sk": "kim6_tubes", "ref": "06.16", "n": 6, "lvl": 2, "q": "[КИМ № 6] В две пробирки с раствором KOH добавили растворы X и Y. В первой выпал голубой осадок, во второй прошла реакция без видимых признаков. Определи X и Y.", "left": ["Вещество X (голубой осадок)", "Вещество Y (реакция без видимых признаков)"], "right": ["CuSO4", "FeCl3", "Na2SO4", "KHCO3", "Ba(NO3)2"], "a": [0, 3], "ex": "X = CuSO4 (1) → голубой осадок Cu(OH)2↓. Y = KHCO3 (4) → нейтрализация кислой соли KHCO3 + KOH → K2CO3 + H2O без видимых признаков. Ответ: 14."}, {"id": "t09_kim6_baco3_trap", "type": "match", "sk": "kim6_tubes", "ref": "06.18", "n": 6, "lvl": 3, "q": "[КИМ № 6] В две пробирки с осадком BaCO3 добавили раствор X (осадок полностью растворился с выделением газа без запаха) и раствор Y (выделился газ без запаха, но белый осадок в пробирке остался). Определи X и Y.", "left": ["Вещество X (полное растворение + газ)", "Вещество Y (газ + остался белый осадок)"], "right": ["H2SO4", "NaOH", "HCl", "K2SO4", "H2SiO3"], "a": [2, 0], "ex": "X = HCl (3): BaCO3 + 2HCl → BaCl2(р-р) + CO2↑ + H2O (полное растворение). Y = H2SO4 (1): BaCO3 + H2SO4 → BaSO4↓ + CO2↑ + H2O (выпадает новый осадок BaSO4↓). Ответ: 31."}, {"id": "t10_kim6_alcl3_nh3", "type": "match", "sk": "kim6_tubes", "ref": "03.31", "n": 6, "lvl": 3, "q": "[КИМ № 6] В две пробирки с раствором AlCl3 добавили избыток раствора X (выпал белый студенистый осадок и НЕ растворился в избытке) и раствор Y (выпал белый осадок и выделился газ с запахом тухлых яиц). Определи X и Y.", "left": ["Вещество X (осадок не растворяется в избытке)", "Вещество Y (белый осадок + газ с запахом тухлых яиц)"], "right": ["NaOH", "NH3·H2O", "Na2CO3", "Na2S", "AgNO3"], "a": [1, 3], "ex": "X = NH3·H2O (2): Al(OH)3↓ не растворяется в избытке водного аммиака (в отличие от NaOH!). Y = Na2S (4): совместный гидролиз до Al(OH)3↓ + H2S↑. Ответ: 24."}, {"id": "t11_kim21_base_asc", "type": "seq", "sk": "kim21_ranking", "ref": "09.9", "n": 21, "lvl": 1, "q": "[КИМ № 21] Расположи водные растворы одинаковой молярной концентрации в порядке ВОЗРАСТАНИЯ pH:", "items": ["HNO3 (сильная кислота)", "Al(NO3)3 (гидролиз по катиону)", "Na2SO4 (гидролиза нет)", "K2CO3 (гидролиз по аниону)"], "why": "HNO3 (pH ≈ 1) < Al(NO3)3 (pH ≈ 4) < Na2SO4 (pH = 7) < K2CO3 (pH ≈ 11)."}, {"id": "t12_kim21_acids_alkalis_desc", "type": "seq", "sk": "kim21_ranking", "ref": "09.12", "n": 21, "lvl": 3, "q": "[КИМ № 21] Расположи водные растворы одинаковой молярной концентрации в порядке УБЫВАНИЯ pH (от самого щелочного к самому кислому!):", "items": ["Ba(OH)2 (двухкислотная щёлочь)", "KOH (однокислотная щёлочь)", "HCl (одноосновная сильная кислота)", "H2SO4 (двухосновная сильная кислота)"], "why": "При равной молярной концентрации: Ba(OH)2 > KOH > HCl > H2SO4."}, {"id": "t13_kim21_acid_salts_asc", "type": "seq", "sk": "kim21_ranking", "ref": "09.18", "n": 21, "lvl": 3, "q": "[КИМ № 21] Расположи водные растворы солей одинаковой молярной концентрации в порядке ВОЗРАСТАНИЯ pH:", "items": ["NaHSO4 (сильнокислая кислая соль)", "NH4Cl (слабокислый гидролиз по катиону)", "NaHCO3 (слабощелочная кислая соль)", "Na2CO3 (средняя соль, сильный гидролиз по аниону)"], "why": "NaHSO4 (≈1,5) < NH4Cl (≈5) < NaHCO3 (≈8,3) < Na2CO3 (≈11,5)."}, {"id": "t14_kim21_organics_desc", "type": "seq", "sk": "kim21_ranking", "ref": "09.21", "n": 21, "lvl": 3, "q": "[КИМ № 21] Расположи водные растворы одинаковой молярной концентрации в порядке УБЫВАНИЯ pH:", "items": ["KOH (сильная щёлочь)", "CH3COONa (гидролиз по аниону)", "C2H5OH (неэлектролит, pH = 7)", "CH3COOH (слабая кислота)"], "why": "Убывание pH: KOH (≈13) > CH3COONa (≈8,9) > C2H5OH (7) > CH3COOH (≈2,9)."}, {"id": "t15_kim21_organics_traps_asc", "type": "seq", "sk": "kim21_ranking", "ref": "09.4", "n": 21, "lvl": 3, "q": "[КИМ № 21] Расположи водные растворы органических веществ одинаковой молярной концентрации в порядке ВОЗРАСТАНИЯ pH:", "items": ["HCOOH (муравьиная кислота)", "C6H5OH (фенол, очень слабая кислота)", "NH2CH2COOH (глицин, pH ≈ 7)", "C6H5ONa (фенолят натрия, щелочная среда)"], "why": "Муравьиная кислота кислее фенола, глицин нейтрален, фенолят натрия гидролизуется по аниону (pH > 7)."}, {"id": "t16_kim21_suffix_trap_asc", "type": "seq", "sk": "kim21_ranking", "ref": "09.24", "n": 21, "lvl": 3, "q": "[КИМ № 21] Ловушка суффиксов (-ат / -ит / -ид)! Расположи водные растворы одинаковой молярной концентрации в порядке ВОЗРАСТАНИЯ pH:", "items": ["NaHSO3 (гидросульфит — слабокислая среда)", "Na2SO4 (сульфат — нейтральная среда)", "Na2SO3 (сульфит — щелочная среда)", "Na2S (сульфид — сильнощелочная среда)"], "why": "H2S слабее H2SO3, поэтому Na2S гидролизуется сильнее, чем Na2SO3. А NaHSO3 входит в кислую тройку кислых солей!"}, {"id": "t17_cross22_hydrolysis_shift", "type": "match", "sk": "hydrolysis_4types", "ref": "07.17", "n": 22, "cross": true, "lvl": 3, "q": "[Связь с № 22] Как сместится равновесие обратимого гидролиза хлорида железа(III) (Fe^{3+} + H2O ⇄ FeOH^{2+} + H^{+} − Q) при указанных воздействиях?", "left": ["Нагревание раствора", "Добавление соляной кислоты HCl", "Добавление раствора NaOH", "Разбавление водой"], "right": ["В сторону продуктов (гидролиз усиливается)", "В сторону реагентов (гидролиз подавляется)", "Не смещается"], "a": [0, 1, 0, 0], "ex": "Нагрев (−Q), разбавление (добавляем H2O) и NaOH (связывает H^{+}) усиливают гидролиз (1); HCl (избыток H^{+}) подавляет гидролиз по катиону (2)."}, {"id": "t18_multi_rio_no_go", "type": "multi", "sk": "joint_hydrolysis_30", "ref": "05.13", "n": 30, "lvl": 3, "q": "Выберите ДВЕ пары веществ, которые НЕЛЬЗЯ использовать для написания реакции ионного обмена в задании № 30.", "o": ["FeCl3 + Na2SO3", "K2Cr2O7 + KOH", "BaCO3 + Na2SO4", "AlCl3 + Na2CO3", "NaH2PO4 + Na3PO4"], "a": [0, 2], "ex": "FeCl3 + Na2SO3 — это скрытая ОВР (Fe^{+3} окисляет S^{+4}); BaCO3 + Na2SO4 — одна из двух солей нерастворима («Н»), обмен двух солей не идёт. Остальные три — полноценные РИО!"}, {"id": "t19_one_indicator_trap", "type": "one", "sk": "ph_scale_acid_salts", "ref": "08.10", "n": 21, "lvl": 2, "q": "В каком растворе фенолфталеин станет МАЛИНОВЫМ, а метилоранж — ЖЁЛТЫМ?", "o": ["NaHCO3", "NaH2PO4", "MgCl2", "CH3COONH4"], "a": 0, "ex": "Обе окраски указывают на щелочную среду (pH > 7). Из перечня щелочную среду имеет только NaHCO3.", "d": {"1": "NaH2PO4 имеет слабокислую среду (ФФ бесцветен).", "2": "MgCl2 гидролизуется по катиону → кислая среда.", "3": "CH3COONH4 имеет нейтральную среду (pH ≈ 7)."}}, {"id": "t20_part2_demo2027_30", "type": "part2", "sk": "rio_conditions", "ref": "03.17", "n": 30, "lvl": 3, "max": 2, "q": "[ДЕМО-2027 ФИПИ, № 30] Перечень веществ: нитрит калия (KNO2), сульфит калия (K2SO3), дихромат калия (K2Cr2O7), серная кислота (H2SO4), иодид калия (KI), гидросульфат аммония (NH4HSO4). Выберите два вещества, реакция ионного обмена между растворами которых сопровождается образованием слабого электролита, причём выделения газа не происходит. Запишите молекулярное, полное и сокращённое ионные уравнения.", "ideal": "МУ:  2KNO2 + H2SO4 → 2HNO2 + K2SO4\nПИУ: 2K^{+} + 2NO2^{−} + 2H^{+} + SO4^{2−} → 2HNO2 + 2K^{+} + SO4^{2−}\nСИУ: H^{+} + NO2^{−} → HNO2\n\n(Также допустим вариант с образованием кислой соли KHSO4: KNO2 + H2SO4 → HNO2 + KHSO4 при согласованной записи HSO4^{−}. K2SO3 не подходит — выделяется газ SO2↑.)", "crit": [["Верно выбраны KNO2 и H2SO4 (без газа!) и записано сбалансированное МУ: 2KNO2 + H2SO4 → 2HNO2 + K2SO4", 1], ["Верно записаны ПИУ (HNO2 не расписана) и СИУ с сокращёнными коэффициентами (H^{+} + NO2^{−} → HNO2) и верным форматом зарядов", 1]], "ex": "Эталон Демоверсии ЕГЭ-2027. Две ловушки: не расписать слабую HNO2 и обязательно сократить двойки в СИУ."}, {"id": "t21_part2_baoh2_nahco3", "type": "part2", "sk": "acid_salts_rio", "ref": "04.20", "n": 30, "lvl": 3, "max": 2, "q": "[КИМ № 30] Перечень веществ: гидроксид бария (Ba(OH)2), гидрокарбонат натрия (NaHCO3), хлорид натрия (NaCl), сульфат калия (K2SO4), азотная кислота (HNO3), медь (Cu). Выберите два вещества, РИО между растворами которых приводит к образованию осадка и щёлочи (только одной соли). Запишите МУ, ПИУ и СИУ.", "ideal": "МУ:  Ba(OH)2 + NaHCO3 → BaCO3↓ + NaOH + H2O\nПИУ: Ba^{2+} + 2OH^{−} + Na^{+} + HCO3^{−} → BaCO3↓ + Na^{+} + OH^{−} + H2O\nСИУ: Ba^{2+} + OH^{−} + HCO3^{−} → BaCO3↓ + H2O", "crit": [["Выбраны Ba(OH)2 и NaHCO3 в соотношении 1:1 и записано сбалансированное МУ с образованием BaCO3↓ и щёлочи NaOH", 1], ["В ПИУ HCO3^{−} не расписан на H^{+}, а в СИУ корректно сокращён один OH^{−}: Ba^{2+} + OH^{−} + HCO3^{−} → BaCO3↓ + H2O", 1]], "ex": "Проверка заряда в СИУ: (+2) + (−1) + (−1) = 0, справа 0."}, {"id": "t22_part2_joint_hydrolysis", "type": "part2", "sk": "joint_hydrolysis_30", "ref": "05.6", "n": 30, "lvl": 3, "max": 2, "q": "[КИМ № 30] Перечень веществ: хлорид железа(III) (FeCl3), сульфид натрия (Na2S), гидрокарбонат натрия (NaHCO3), сульфат калия (K2SO4), оксид кальция (CaO), иодид калия (KI). Выберите два вещества, РИО между растворами которых сопровождается выпадением бурого осадка и выделением газа без запаха. Запишите МУ, ПИУ и СИУ.", "ideal": "МУ:  FeCl3 + 3NaHCO3 → Fe(OH)3↓ + 3CO2↑ + 3NaCl\nПИУ: Fe^{3+} + 3Cl^{−} + 3Na^{+} + 3HCO3^{−} → Fe(OH)3↓ + 3CO2↑ + 3Na^{+} + 3Cl^{−}\nСИУ: Fe^{3+} + 3HCO3^{−} → Fe(OH)3↓ + 3CO2↑\n\n(Пары FeCl3 + Na2S и FeCl3 + KI — это ОВР, они запрещены в № 30!)", "crit": [["Выбрана пара FeCl3 + NaHCO3 (а не ОВР с Na2S/KI) и записано МУ без лишней воды: FeCl3 + 3NaHCO3 → Fe(OH)3 + 3CO2 + 3NaCl", 1], ["Верно записаны ПИУ (HCO3^{−} целый) и СИУ: Fe^{3+} + 3HCO3^{−} → Fe(OH)3↓ + 3CO2↑ с верным форматом зарядов", 1]], "ex": "Проверка баланса в СИУ: 1 Fe, 3 H, 3 C, 9 O, заряд (+3) + 3·(−1) = 0."}, {"id": "t23_part2_complex_dissolve", "type": "part2", "sk": "rio_conditions", "ref": "03.29", "n": 30, "lvl": 3, "max": 2, "q": "[КИМ № 30] Перечень веществ: тетрагидроксоалюминат натрия (Na[Al(OH)4]), соляная кислота (HCl), хлорид натрия (NaCl), сульфат калия (K2SO4), гидроксид калия (KOH), железо (Fe). Выберите два вещества, РИО между растворами которых (при недостатке кислоты) приводит к выпадению белого студенистого осадка. Запишите МУ, ПИУ и СИУ.", "ideal": "МУ:  Na[Al(OH)4] + HCl → Al(OH)3↓ + NaCl + H2O\nПИУ: Na^{+} + [Al(OH)4]^{−} + H^{+} + Cl^{−} → Al(OH)3↓ + Na^{+} + Cl^{−} + H2O\nСИУ: [Al(OH)4]^{−} + H^{+} → Al(OH)3↓ + H2O", "crit": [["Выбраны Na[Al(OH)4] и HCl (1:1) и записано сбалансированное МУ с выпадением Al(OH)3↓", 1], ["В ПИУ и СИУ комплексный анион [Al(OH)4]^{−} записан целиком без разбивания квадратных скобок", 1]], "ex": "В избытке HCl (1:4) осадок растворился бы до AlCl3, поэтому для выпадения осадка нужно именно 1:1."}, {"id": "t24_part2_chromate_shift", "type": "part2", "sk": "joint_hydrolysis_30", "ref": "05.15", "n": 30, "lvl": 3, "max": 2, "q": "[КИМ № 30] Перечень веществ: дихромат калия (K2Cr2O7), гидроксид калия (KOH), нитрат натрия (NaNO3), хлорид бария (BaCl2), иодид калия (KI), серная кислота (H2SO4). Выберите два вещества, РИО между растворами которых сопровождается переходом оранжевой окраски раствора в жёлтую без выпадения осадка и без выделения газа. Запишите МУ, ПИУ и СИУ.", "ideal": "МУ:  K2Cr2O7 + 2KOH → 2K2CrO4 + H2O\nПИУ: 2K^{+} + Cr2O7^{2−} + 2K^{+} + 2OH^{−} → 4K^{+} + 2CrO4^{2−} + H2O\nСИУ: Cr2O7^{2−} + 2OH^{−} → 2CrO4^{2−} + H2O", "crit": [["Выбрана пара K2Cr2O7 + KOH (не ОВР, везде Cr^{+6}) и записано сбалансированное МУ", 1], ["Верно записаны ПИУ и СИУ: Cr2O7^{2−} + 2OH^{−} → 2CrO4^{2−} + H2O с балансом зарядов (−4 слева и −4 справа)", 1]], "ex": "Проверка зарядов в СИУ: (−2) + 2·(−1) = −4; справа 2·(−2) = −4."}], "subjectSlug": "chemistry", "_kim": {"6": {"b": 2, "l": "П"}, "21": {"b": 1, "l": "Б"}, "22": {"b": 2, "l": "П"}, "30": {"b": 2, "l": "В"}}, "_kon": {"01": {"t": "Модуль 01. Электролитическая диссоциация: почему растворы проводят ток", "x": "Вещества с ионной или сильно полярной ковалентной связью в воде распадаются на подвижные заряженные частицы — ионы. Именно эти ионы переносят электрический заряд, а само явление называется [[электролитическая диссоциация|электролитической диссоциацией]]."}, "01.1": {"t": "Модуль 01 · Главная мысль.", "x": "Вещества с ионной или сильно полярной ковалентной связью в воде распадаются на подвижные заряженные частицы — ионы. Именно эти ионы переносят электрический заряд, а само явление называется [[электролитическая диссоциация|электролитической диссоциацией]]."}, "01.16": {"t": "Модуль 01 · 3. Степень диссоциации α и от чего она зависит", "x": "α = N_{дисс} / N_{общ}   (в долях от 0 до 1, или × 100%)"}, "01.19": {"t": "Модуль 01 · 4. Сильные и слабые электролиты: твёрдый список для ЕГЭ", "x": "По степени диссоциации в разбавленных водных растворах электролиты делят на **сильные** (α > 30%, в школьной модели условно считают α ≈ 100%, пишут стрелку →), **средней силы** (3% < α < 30%, например H3PO4, HF, H2SO3) и **слабые** (α < 3%, пишут обратимую стрелку ⇄). В заданиях ЕГЭ по ионным уравнениям **средние и слабые электролиты ведут себя одинаково**: их на ионы **не** расписывают.\n• ****Кислоты**** — Сильные электролиты (распадаются полностью): 9 кислот для ЕГЭ: HCl, HBr, HI, HNO3, H2SO4, HClO4, HClO3, HMnO4, H2Cr2O7; Слабые и средние электролиты (в ПИУ пишутся молекулой): Все остальные: HF, H2S, HNO2, H3PO4, H2CO3, H2SO3, H2SiO3, HClO, HCN, HCOOH, CH3COOH и другие органические кислоты…"}, "01.21": {"t": "Модуль 01 · 4. Сильные и слабые электролиты: твёрдый список для ЕГЭ", "x": "• ****Кислоты**** — Сильные электролиты (распадаются полностью): 9 кислот для ЕГЭ: HCl, HBr, HI, HNO3, H2SO4, HClO4, HClO3, HMnO4, H2Cr2O7; Слабые и средние электролиты (в ПИУ пишутся молекулой): Все остальные: HF, H2S, HNO2, H3PO4, H2CO3, H2SO3, H2SiO3, HClO, HCN, HCOOH, CH3COOH и другие органические кислоты\n• ****Основания**** — Сильные электролиты (распадаются полностью): Щёлочи (гидроксиды щелочных и щёлочноземельных металлов): LiOH, NaOH, KOH, RbOH, CsOH, Ba(OH)2, а также водные растворы Ca(OH)2, Sr(OH)2; Слабые и средние электролиты (в ПИУ пишутся молекулой): Водный аммиак NH3·H2O, амины в воде, все нерастворимые основания и амфотерные гидроксиды (Mg(OH)2, Cu(OH)2, Fe(OH)3, Al(OH)3, Zn(OH)2)…"}, "01.25": {"t": "Модуль 01 · 5. Ступенчатая диссоциация многоосновных кислот", "x": "1-я ступень (основная): H3PO4 ⇄ H^{+} + H2PO4^{−}\n2-я ступень (слабее):   H2PO4^{−} ⇄ H^{+} + HPO4^{2−}\n3-я ступень (едва идёт): HPO4^{2−} ⇄ H^{+} + PO4^{3−}"}, "02": {"t": "Модуль 02. Таблица растворимости ФИПИ и анатомия ионных уравнений", "x": "На ЕГЭ твоя главная опора в ионных уравнениях — официальная таблица растворимости ФИПИ. В **полном ионном уравнении (ПИУ)** на ионы расписываются только сильные растворимые электролиты, а в **сокращённом (СИУ)** убираются одинаковые ионы-наблюдатели и сокращаются общие множители."}, "02.1": {"t": "Модуль 02 · Главная мысль.", "x": "На ЕГЭ твоя главная опора в ионных уравнениях — официальная таблица растворимости ФИПИ. В **полном ионном уравнении (ПИУ)** на ионы расписываются только сильные растворимые электролиты, а в **сокращённом (СИУ)** убираются одинаковые ионы-наблюдатели и сокращаются общие множители."}, "02.9": {"t": "Модуль 02 · 2. Условности и сюрпризы таблицы ФИПИ-2027", "x": "• **Ca(CH3COO)2 — стоит прочерк «–»:** это условность бланка ФИПИ ЕГЭ-2027 (в реальной химии ацетат кальция хорошо растворим в воде). В задании № 30 слева такую соль выбирать нельзя, чтобы не вступать в противоречие с официальной таблицей.\n• **Ba(HCO3)2, Mg(HCO3)2, Sr(HCO3)2 — стоит прочерк «–»:** эти гидрокарбонаты существуют в водных растворах, но разлагаются при выпаривании и не выделяются в сухом виде. В таблице ФИПИ пометка «Р» среди щёлочноземельных гидрокарбонатов стоит только у Ca(HCO3)2.\n• **(NH4)3PO4 — стоит прочерк «–»:** в воде соль хорошо растворима, но в твёрдом виде легко теряет аммиак на воздухе, переходя в (NH4)2HPO4 (у которого в таблице стоит «Р»).\n• **Соли лития:** в отличие от солей Na^{+} и K^{+}, далеко не все соли лития растворимы! В таблице ФИПИ Li3PO4 и Li2SiO3 имеют статус **«Н»** (осадки), LiF — **«М»**, а вот Li2CO3 — **«Р»**.…"}, "02.12": {"t": "Модуль 02 · 3. Позиционное правило для Ca(OH)2 и Sr(OH)2", "x": "**Шаг 1.** **Слева (в реагентах):** на ЕГЭ обычно берут прозрачный раствор — известковую воду Ca(OH)2 (или стронциевую воду Sr(OH)2). Все молекулы, которые перешли в раствор, полностью диссоциировали на ионы → **расписываем на ионы** Ca^{2+} + 2OH^{−}.\n**Шаг 2.** **Справа (в продуктах):** если смешать концентрированные растворы CaCl2 и NaOH, концентрация Ca^{2+} и OH^{−} превышает предел растворимости, и Ca(OH)2 выпадает в белый осадок → **пишем молекулой** Ca(OH)2↓."}, "02.13": {"t": "Модуль 02 · 3. Позиционное правило для Ca(OH)2 и Sr(OH)2", "x": "Слева (раствор):  МУ:  Ca(OH)2 + 2HCl → CaCl2 + 2H2O\nПИУ: Ca^{2+} + 2OH^{−} + 2H^{+} + 2Cl^{−} → Ca^{2+} + 2Cl^{−} + 2H2O\nСИУ: H^{+} + OH^{−} → H2O"}, "02.14": {"t": "Модуль 02 · 3. Позиционное правило для Ca(OH)2 и Sr(OH)2", "x": "Справа (осадок):  МУ:  CaCl2 + 2NaOH → Ca(OH)2↓ + 2NaCl\nПИУ: Ca^{2+} + 2Cl^{−} + 2Na^{+} + 2OH^{−} → Ca(OH)2↓ + 2Na^{+} + 2Cl^{−}\nСИУ: Ca^{2+} + 2OH^{−} → Ca(OH)2↓"}, "02.17": {"t": "Модуль 02 · 4. Пять строгих правил оформления ПИУ и СИУ на 2/2 балла", "x": "1. **Заряд иона — сначала цифра, потом знак!** Пиши Fe^{2+}, Fe^{3+}, SO4^{2−}, PO4^{3−}, OH^{−}, H^{+} (единицу не пишем). Запись со знаком впереди (Fe^{+2}, SO4^{−2}) — это **степень окисления**, а не заряд иона; в № 30 за такую подмену снимают балл за ионные уравнения.\n2. **Никакого NH4OH!** Гидроксид аммония в виде молекулы NH4OH не существует. Если реакция с солью аммония и щёлочью идёт без выделения газа (разбавленный раствор, без нагревания), пиши NH3·H2O (слабый электролит, в ПИУ не расписывается); если по условию выделяется газ (при нагревании), пиши NH3↑ + H2O.\n3. **В СИУ обязательно сокращай кратные коэффициенты!** Если после вычёркивания ионов-наблюдателей получилось 2H^{+} + 2OH^{−} → 2H2O, раздели все коэффициенты на 2 и запиши H^{+} + OH^{−} → H2O. Несокращённые коэффициенты в СИУ обнуляют второй балл в № 30.…"}, "03": {"t": "Модуль 03. Условия протекания РИО: осадок, газ, слабый электролит", "x": "**[[Реакция ионного обмена]] (РИО)** — это реакция между электролитами в водном растворе без изменения степеней окисления. Она идёт до конца (необратимо) тогда и только тогда, когда хотя бы часть ионов «выходит из игры» — связывается в **осадок**, **газ** или **слабый электролит**."}, "03.1": {"t": "Модуль 03 · Главная мысль.", "x": "**[[Реакция ионного обмена]] (РИО)** — это реакция между электролитами в водном растворе без изменения степеней окисления. Она идёт до конца (необратимо) тогда и только тогда, когда хотя бы часть ионов «выходит из игры» — связывается в **осадок**, **газ** или **слабый электролит**."}, "03.10": {"t": "Модуль 03 · Условие А: выпадение осадка («Н» или «М» в таблице ФИПИ)", "x": "МУ:  BaCl2 + Na2SO4 → BaSO4↓ + 2NaCl\nПИУ: Ba^{2+} + 2Cl^{−} + 2Na^{+} + SO4^{2−} → BaSO4↓ + 2Na^{+} + 2Cl^{−}\nСИУ: Ba^{2+} + SO4^{2−} → BaSO4↓"}, "03.13": {"t": "Модуль 03 · Условие Б: выделение газа (CO2↑, SO2↑, H2S↑, NH3↑)", "x": "МУ:  Na2CO3 + 2HCl → 2NaCl + CO2↑ + H2O\nПИУ: 2Na^{+} + CO3^{2−} + 2H^{+} + 2Cl^{−} → 2Na^{+} + 2Cl^{−} + CO2↑ + H2O\nСИУ: CO3^{2−} + 2H^{+} → CO2↑ + H2O"}, "03.14": {"t": "Модуль 03 · Условие Б: выделение газа (CO2↑, SO2↑, H2S↑, NH3↑)", "x": "МУ:  NH4Cl + NaOH —t°→ NaCl + NH3↑ + H2O\nПИУ: NH4^{+} + Cl^{−} + Na^{+} + OH^{−} —t°→ Na^{+} + Cl^{−} + NH3↑ + H2O\nСИУ: NH4^{+} + OH^{−} —t°→ NH3↑ + H2O"}, "03.17": {"t": "Модуль 03 · Условие В: образование слабого электролита без осадка и газа", "x": "Разберём вслух эталонную задачу из **демоверсии ФИПИ ЕГЭ-2027 (№ 30)**: из перечня *нитрит калия, сульфит калия, дихромат калия, серная кислота, иодид калия, гидросульфат аммония* нужно выбрать два вещества, РИО между растворами которых сопровождается образованием слабого электролита, а выделения газа не происходит."}, "03.19": {"t": "Модуль 03 · Условие В: образование слабого электролита без осадка и газа", "x": "МУ:  2KNO2 + H2SO4(разб.) → 2HNO2 + K2SO4\nПИУ: 2K^{+} + 2NO2^{−} + 2H^{+} + SO4^{2−} → 2HNO2 + 2K^{+} + SO4^{2−}\nСИУ: H^{+} + NO2^{−} → HNO2"}, "03.24": {"t": "Модуль 03 · 3. Растворение осадков и комплексообразование в РИО", "x": "**Шаг 1.** **Растворение амфотерного гидроксида Al(OH)3 в сильной кислоте (HCl):** осадок Al(OH)3 слева пишем молекулой, сильную кислоту HCl и растворимую соль AlCl3 справа — ионами. Проверяем баланс по O: слева 3, справа 3; заряд слева 3+, справа 3+.\n**Шаг 2.** **Растворение Al(OH)3 в избытке водной щёлочи (NaOH):** образуется растворимая комплексная соль — тетрагидроксоалюминат натрия Na[Al(OH)4]. В ПИУ комплексная соль распадается на катион Na^{+} и **целый** комплексный анион [Al(OH)4]^{−} (внутреннюю сферу в квадратных скобках никогда не разбивают на Al^{3+} и OH^{−}!)."}, "03.25": {"t": "Модуль 03 · 3. Растворение осадков и комплексообразование в РИО", "x": "МУ:  Al(OH)3 + 3HCl → AlCl3 + 3H2O\nПИУ: Al(OH)3 + 3H^{+} + 3Cl^{−} → Al^{3+} + 3Cl^{−} + 3H2O\nСИУ: Al(OH)3 + 3H^{+} → Al^{3+} + 3H2O"}, "03.26": {"t": "Модуль 03 · 3. Растворение осадков и комплексообразование в РИО", "x": "МУ:  Al(OH)3 + NaOH → Na[Al(OH)4]\nПИУ: Al(OH)3 + Na^{+} + OH^{−} → Na^{+} + [Al(OH)4]^{−}\nСИУ: Al(OH)3 + OH^{−} → [Al(OH)4]^{−}"}, "03.29": {"t": "Модуль 03 · 3. Растворение осадков и комплексообразование в РИО", "x": "Недостаток кислоты (выпадает осадок Al(OH)3↓):\nМУ:  Na[Al(OH)4] + HCl → Al(OH)3↓ + NaCl + H2O\nПИУ: Na^{+} + [Al(OH)4]^{−} + H^{+} + Cl^{−} → Al(OH)3↓ + Na^{+} + Cl^{−} + H2O\nСИУ: [Al(OH)4]^{−} + H^{+} → Al(OH)3↓ + H2O"}, "03.30": {"t": "Модуль 03 · 3. Растворение осадков и комплексообразование в РИО", "x": "Избыток сильной кислоты (полное растворение комплекса до соли Al^{3+}):\nМУ:  Na[Al(OH)4] + 4HCl → AlCl3 + NaCl + 4H2O\nПИУ: Na^{+} + [Al(OH)4]^{−} + 4H^{+} + 4Cl^{−} → Al^{3+} + 3Cl^{−} + Na^{+} + Cl^{−} + 4H2O\nСИУ: [Al(OH)4]^{−} + 4H^{+} → Al^{3+} + 4H2O"}, "03.31": {"t": "Модуль 03 · 3. Растворение осадков и комплексообразование в РИО", "x": "Осаждение Al(OH)3 водным аммиаком (в избытке NH3·H2O осадок НЕ растворяется!):\nМУ:  AlCl3 + 3NH3·H2O → Al(OH)3↓ + 3NH4Cl\nПИУ: Al^{3+} + 3Cl^{−} + 3NH3·H2O → Al(OH)3↓ + 3NH4^{+} + 3Cl^{−}\nСИУ: Al^{3+} + 3NH3·H2O → Al(OH)3↓ + 3NH4^{+}"}, "03.33": {"t": "Модуль 03 · 4. Особые случаи: «две соли» и прочерки Ag^{+} / Hg^{2+} со щёлочью", "x": "• **Правило двух солей:** если в реакцию обмена вступают **две соли**, в школьном курсе ЕГЭ **обе исходные соли должны быть растворимы («Р»)** в таблице ФИПИ. Реакции вида BaCO3 + Na2SO4 или AgCl + NaI в рамках № 30 не используют: твёрдые осадки солей с растворами других солей практически не обмениваются.\n• **Правило «сильная кислота вытесняет слабую, но не наоборот»:** CaCO3 + 2HCl → CaCl2 + CO2↑ + H2O идёт бурно, а вот BaSO4 + 2HCl или AgCl + HNO3 **не идут**, потому что BaSO4 и AgCl — соли сильных кислот и в сильных кислотах не растворяются. Исключение среди слабых кислот — нерастворимая кремниевая кислота H2SiO3↓, которая сама выпадает в осадок (Na2SiO3 + 2HCl → H2SiO3↓ + 2NaCl).…"}, "04": {"t": "Модуль 04. Кислые соли в РИО: избыток/недостаток и дилемма HSO4⁻", "x": "**[[Кислая соль]]** содержит в анионе недозамещённый атом водорода (HCO3^{−}, HSO3^{−}, HS^{−}, H2PO4^{−}, HPO4^{2−}, HSO4^{−}). В воде растворимая кислая соль распадается на катион металла и **целый кислый анион**; лишь для HSO4^{−} ФИПИ допускает расписывание на H^{+} + SO4^{2−} при строгой согласованности обеих частей уравнения."}, "04.1": {"t": "Модуль 04 · Главная мысль.", "x": "**[[Кислая соль]]** содержит в анионе недозамещённый атом водорода (HCO3^{−}, HSO3^{−}, HS^{−}, H2PO4^{−}, HPO4^{2−}, HSO4^{−}). В воде растворимая кислая соль распадается на катион металла и **целый кислый анион**; лишь для HSO4^{−} ФИПИ допускает расписывание на H^{+} + SO4^{2−} при строгой согласованности обеих частей уравнения."}, "04.4": {"t": "Модуль 04 · 1. Как диссоциируют кислые соли: слабые анионы vs HSO4⁻", "x": "NaHCO3 → Na^{+} + HCO3^{−}     (в ПИУ писать H^{+} + CO3^{2−} ЗАПРЕЩЕНО!)\nNaH2PO4 → Na^{+} + H2PO4^{−}   (аналогично: HSO3^{−}, HS^{−}, HPO4^{2−} — единые ионы)"}, "04.7": {"t": "Модуль 04 · Ловушка ЕГЭ: согласованность записи HSO4⁻", "x": "**Правило согласованности сторон для HSO4^{−}:** если ты оставил HSO4^{−} нерасписанным слева, то и справа (если он там есть) его нельзя расписывать, и наоборот — нельзя в одном и том же ПИУ расписать NaHSO4 как Na^{+} + HSO4^{−}, а справа получить SO4^{2−} «из воздуха» без переноса протона. Линтер и эксперт ФИПИ проверяют баланс каждого иона!"}, "04.14": {"t": "Модуль 04 · Тип 1. Кислая соль + щёлочь с одноимённым катионом", "x": "МУ:  NaHCO3 + NaOH → Na2CO3 + H2O\nПИУ: Na^{+} + HCO3^{−} + Na^{+} + OH^{−} → 2Na^{+} + CO3^{2−} + H2O\nСИУ: HCO3^{−} + OH^{−} → CO3^{2−} + H2O"}, "04.16": {"t": "Модуль 04 · Тип 1. Кислая соль + щёлочь с одноимённым катионом", "x": "МУ:  Ca(HCO3)2 + Ca(OH)2 → 2CaCO3↓ + 2H2O\nПИУ: Ca^{2+} + 2HCO3^{−} + Ca^{2+} + 2OH^{−} → 2CaCO3↓ + 2H2O\nСИУ: Ca^{2+} + HCO3^{−} + OH^{−} → CaCO3↓ + H2O"}, "04.20": {"t": "Модуль 04 · Тип 2. Кислая соль + щёлочь с разноимённым катионом (Ba(OH)2 + NaHCO3)", "x": "1:1 (изб. Ba(OH)2):  МУ:  Ba(OH)2 + NaHCO3 → BaCO3↓ + NaOH + H2O\nПИУ: Ba^{2+} + 2OH^{−} + Na^{+} + HCO3^{−} → BaCO3↓ + Na^{+} + OH^{−} + H2O\nСИУ: Ba^{2+} + OH^{−} + HCO3^{−} → BaCO3↓ + H2O"}, "04.21": {"t": "Модуль 04 · Тип 2. Кислая соль + щёлочь с разноимённым катионом (Ba(OH)2 + NaHCO3)", "x": "1:2 (изб. NaHCO3):   МУ:  Ba(OH)2 + 2NaHCO3 → BaCO3↓ + Na2CO3 + 2H2O\nПИУ: Ba^{2+} + 2OH^{−} + 2Na^{+} + 2HCO3^{−} → BaCO3↓ + 2Na^{+} + CO3^{2−} + 2H2O\nСИУ: Ba^{2+} + 2OH^{−} + 2HCO3^{−} → BaCO3↓ + CO3^{2−} + 2H2O"}, "04.25": {"t": "Модуль 04 · Тип 3. Гидросульфат NaHSO4 (или KHSO4) в роли кислоты", "x": "С солью слабой кислоты (запись с целым HSO4^{−}):\nМУ:  NaHSO4 + NaHCO3 → Na2SO4 + CO2↑ + H2O\nПИУ: Na^{+} + HSO4^{−} + Na^{+} + HCO3^{−} → 2Na^{+} + SO4^{2−} + CO2↑ + H2O\nСИУ: HSO4^{−} + HCO3^{−} → SO4^{2−} + CO2↑ + H2O"}, "04.26": {"t": "Модуль 04 · Тип 3. Гидросульфат NaHSO4 (или KHSO4) в роли кислоты", "x": "С хлоридом бария (каноническое соотношение 1:1; полный распад HSO4^{−}):\nМУ:  NaHSO4 + BaCl2 → BaSO4↓ + NaCl + HCl\nПИУ: Na^{+} + H^{+} + SO4^{2−} + Ba^{2+} + 2Cl^{−} → BaSO4↓ + Na^{+} + H^{+} + 2Cl^{−}\nСИУ: Ba^{2+} + SO4^{2−} → BaSO4↓"}, "04.30": {"t": "Модуль 04 · Тип 4. Встреча кислой и средней соли одной кислоты (перераспределение протонов)", "x": "МУ:  NaH2PO4 + Na3PO4 → 2Na2HPO4\nПИУ: Na^{+} + H2PO4^{−} + 3Na^{+} + PO4^{3−} → 4Na^{+} + 2HPO4^{2−}\nСИУ: H2PO4^{−} + PO4^{3−} → 2HPO4^{2−}"}, "04.31": {"t": "Модуль 04 · Ловушка ЕГЭ: Na2HPO3 и NaH2PO2 — не кислые соли!", "x": "**Псевдокислые средние соли фосфора (Na2HPO3, NaH2PO2):** фосфористая кислота H3PO3 — **двухосновна** (один атом H связан напрямую с фосфором и не замещается на металл), а фосфорноватистая H3PO2 — **одноосновна**. Поэтому Na2HPO3 (фосфит натрия) и NaH2PO2 (гипофосфит натрия) — это **средние соли**: в № 30 они **не** вступают в нейтрализацию со щёлочью, а в № 21 гидролизуются по аниону и дают щелочную среду."}, "05": {"t": "Модуль 05. Совместный гидролиз и границы РИО в задании № 30", "x": "**[[Совместный гидролиз]]** (взаимное усиление гидролиза) — это РИО между растворимой солью слабого основания (Al^{3+}, Cr^{3+}, Fe^{3+}) и растворимой солью слабой летучей кислоты, приводящая одновременно к **осадку гидроксида** и **выделению газа**. Но не каждый «прочерк» в таблице ФИПИ является РИО: многие из них — это **скрытые ОВР**, строго запрещённые в задании № 30!"}, "05.1": {"t": "Модуль 05 · Главная мысль.", "x": "**[[Совместный гидролиз]]** (взаимное усиление гидролиза) — это РИО между растворимой солью слабого основания (Al^{3+}, Cr^{3+}, Fe^{3+}) и растворимой солью слабой летучей кислоты, приводящая одновременно к **осадку гидроксида** и **выделению газа**. Но не каждый «прочерк» в таблице ФИПИ является РИО: многие из них — это **скрытые ОВР**, строго запрещённые в задании № 30!"}, "05.5": {"t": "Модуль 05 · 1. Механизм совместного (необратимого) гидролиза", "x": "МУ:  2AlCl3 + 3Na2CO3 + 3H2O → 2Al(OH)3↓ + 3CO2↑ + 6NaCl\nПИУ: 2Al^{3+} + 6Cl^{−} + 6Na^{+} + 3CO3^{2−} + 3H2O → 2Al(OH)3↓ + 3CO2↑ + 6Na^{+} + 6Cl^{−}\nСИУ: 2Al^{3+} + 3CO3^{2−} + 3H2O → 2Al(OH)3↓ + 3CO2↑"}, "05.6": {"t": "Модуль 05 · 1. Механизм совместного (необратимого) гидролиза", "x": "С гидрокарбонатом (вода в уравнении не требуется — проверь баланс H и O!):\nМУ:  FeCl3 + 3NaHCO3 → Fe(OH)3↓ + 3CO2↑ + 3NaCl\nПИУ: Fe^{3+} + 3Cl^{−} + 3Na^{+} + 3HCO3^{−} → Fe(OH)3↓ + 3CO2↑ + 3Na^{+} + 3Cl^{−}\nСИУ: Fe^{3+} + 3HCO3^{−} → Fe(OH)3↓ + 3CO2↑"}, "05.10": {"t": "Модуль 05 · 2. Чёткая граница: какие «прочерки» — это РИО, а какие — скрытые ОВР", "x": "• **Al^{3+} или Cr^{3+} + CO3^{2−} / HCO3^{−}** — Тип реакции: **РИО** (совместный гидролиз); Продукты и признак: Al(OH)3↓ (белый) или Cr(OH)3↓ (серо-зелёный) + CO2↑; Можно ли в № 30?: **Да** (осадок + газ без запаха)\n• **Al^{3+} или Cr^{3+} + S^{2−} / HS^{−}** — Тип реакции: **РИО** (совместный гидролиз); Продукты и признак: Al(OH)3↓ или Cr(OH)3↓ + H2S↑; Можно ли в № 30?: **Да** (осадок + газ с запахом тухлых яиц)\n• **Al^{3+} или Cr^{3+} + SO3^{2−} / HSO3^{−}** — Тип реакции: **РИО** (совместный гидролиз); Продукты и признак: Al(OH)3↓ или Cr(OH)3↓ + SO2↑; Можно ли в № 30?: **Да** (осадок + газ с резким запахом)\n• **Fe^{3+} + CO3^{2−} / HCO3^{−}** — Тип реакции: **РИО** (совместный гидролиз); Продукты и признак: Fe(OH)3↓ (бурый) + CO2↑ (C^{+4} не восстановитель!); Можно ли в № 30?: **Да** (бурый осадок + газ без запаха)…"}, "05.13": {"t": "Модуль 05 · 3. Что ещё строго запрещено выбирать в задании № 30", "x": "• **Любые ОВР:** кроме скрытых пар выше, сюда же относятся KMnO4 / K2Cr2O7 с восстановителями, HNO3 с сульфидами/сульфитами/иодидами/солями Fe^{2+}, диспропорционирование Cl2 + NaOH.\n• **Реакции с неэлектролитами (оксидами и простыми веществами):** CaO + 2HCl, CO2 + Ba(OH)2, Zn + 2HCl, Fe + CuSO4. Это не РИО — в № 30 оба исходных вещества должны быть электролитами (кислота, щёлочь, соль или гидроксид, если условие допускает осадок).\n• **Реакции твёрдых солей с концентрированной серной кислотой:** NaCl(тв.) + H2SO4(конц.) —t°→ NaHSO4 + HCl↑. Это вытеснение летучей кислоты при нагревании без водного раствора, а не РИО в растворе.\n• **Две соли, если хотя бы одна нерастворима («Н» / «М» / «–»):** обе исходные соли в обменной реакции двух солей должны иметь пометку «Р» в таблице ФИПИ."}, "05.14": {"t": "Модуль 05 · Важное исключение для № 30: переход CrO4²⁻ ↔ Cr2O7²⁻ — это РИО, а не ОВР!", "x": "Не отбрасывай по ошибке **переход хромат ↔ дихромат**! В реакциях K2Cr2O7 со щёлочью и K2CrO4 с сильной кислотой степень окисления хрома (Cr^{+6}) **не меняется** — это полноценная **РИО** (с признаком «изменение окраски раствора без осадка и газа»):"}, "05.15": {"t": "Модуль 05 · 3. Что ещё строго запрещено выбирать в задании № 30", "x": "Дихромат (оранжевый) → хромат (жёлтый) в щелочной среде:\nМУ:  K2Cr2O7 + 2KOH → 2K2CrO4 + H2O\nПИУ: 2K^{+} + Cr2O7^{2−} + 2K^{+} + 2OH^{−} → 4K^{+} + 2CrO4^{2−} + H2O\nСИУ: Cr2O7^{2−} + 2OH^{−} → 2CrO4^{2−} + H2O"}, "05.16": {"t": "Модуль 05 · 3. Что ещё строго запрещено выбирать в задании № 30", "x": "Хромат (жёлтый) → дихромат (оранжевый) в кислой среде:\nМУ:  2K2CrO4 + H2SO4(разб.) → K2Cr2O7 + K2SO4 + H2O\nПИУ: 4K^{+} + 2CrO4^{2−} + 2H^{+} + SO4^{2−} → 2K^{+} + Cr2O7^{2−} + 2K^{+} + SO4^{2−} + H2O\nСИУ: 2CrO4^{2−} + 2H^{+} → Cr2O7^{2−} + H2O"}, "05.17": {"t": "Модуль 05 · Алгоритм проверки пары веществ для задания № 30", "x": "• Меняется ли степень окисления хотя бы у одного элемента (есть пара окислитель + восстановитель)?\n• Да → **Пара НЕ подходит для № 30!** (Это ОВР (возможно, она предназначена для задания № 29). В № 30 степени окисления всех элементов должны остаться неизменными.)\n• Нет → Оба исходных вещества — электролиты (нет оксидов, простых веществ, неэлектролитов и твёрдых солей с H2SO4(конц.))?\n• Да → Если реагируют две соли, у ОБЕИХ стоит «Р» в таблице ФИПИ? (Если кислота/щёлочь + осадок, то реагент — сильный электролит?)\n• Да → Среди продуктов есть осадок («Н»/«М»), газ (CO2, SO2, H2S, NH3) или слабый электролит (H2O, NH3·H2O, слабая кислота), И он точно соответствует формулировке условия?\n• Да → **Пара ПОДХОДИТ! Пиши МУ → ПИУ → СИУ.** (Выполнены все требования ФИПИ: это необратимая РИО, попадающая точно в условие задачи.)…"}, "06": {"t": "Модуль 06. Пробирки X и Y: качественные признаки РИО в задании № 6", "x": "Задание № 6 проверяет умение переводить **визуальные признаки РИО** (выпадение или растворение осадка, цвет, выделение газа, отсутствие видимых признаков) в конкретные ионные уравнения. За него дают **2 балла**, и **порядок цифр X и Y строго фиксирован**."}, "06.1": {"t": "Модуль 06 · Главная мысль.", "x": "Задание № 6 проверяет умение переводить **визуальные признаки РИО** (выпадение или растворение осадка, цвет, выделение газа, отсутствие видимых признаков) в конкретные ионные уравнения. За него дают **2 балла**, и **порядок цифр X и Y строго фиксирован**."}, "06.7": {"t": "Модуль 06 · 2. Карта качественных признаков осадков и газов для № 6", "x": "• ****Белый осадок, нерастворимый в кислотах**** — Вещества и формулы: BaSO4, AgCl, PbSO4, H2SiO3 (студенистый); На что обратить внимание: Отличает сульфаты (BaSO4) и хлориды (AgCl) от карбонатов и сульфитов.\n• ****Белый осадок, растворимый в кислотах с газом**** — Вещества и формулы: CaCO3, BaCO3, BaSO3; На что обратить внимание: С сильной кислотой CO3^{2−} даёт CO2↑ без запаха, SO3^{2−} — SO2↑ с резким запахом.\n• ****Белый амфотерный осадок**** — Вещества и формулы: Al(OH)3, Zn(OH)2, Be(OH)2; На что обратить внимание: Растворяется **и в сильной кислоте, и в избытке щёлочи** (без выделения газа!). Из раствора Al^{3+} осаждается и водным аммиаком NH3·H2O, но в избытке NH3·H2O **не** растворяется.…"}, "06.10": {"t": "Модуль 06 · Задача 1. Две пробирки с осадком гидроксида цинка (Zn(OH)2)", "x": "**Условие:** В две пробирки с осадком Zn(OH)2 добавили растворы веществ X и Y. В первой пробирке осадок растворился с образованием соли цинка(II), во второй — растворился с образованием комплексной соли. Из списка *(1) NaCl, (2) KOH, (3) H2SiO3, (4) HNO3, (5) Ba(NO3)2* выберите X и Y."}, "06.11": {"t": "Модуль 06 · Задача 1. Две пробирки с осадком гидроксида цинка (Zn(OH)2)", "x": "**Шаг 1.** **Определяем природу стартового вещества:** Zn(OH)2 — нерастворимый **амфотерный гидроксид**. С обычными средними солями (NaCl, Ba(NO3)2) осадок гидроксида не реагирует.\n**Шаг 2.** **Подбираем X (растворение с образованием соли цинка):** нужна сильная растворимая кислота. Кремниевая кислота H2SiO3 нерастворима («Н») и с осадком не реагирует. Подходит HNO3 (4): Zn(OH)2 + 2HNO3 → Zn(NO3)2 + 2H2O.\n**Шаг 3.** **Подбираем Y (растворение с образованием комплексной соли):** нужна щёлочь. Подходит KOH (2): Zn(OH)2 + 2KOH → K2[Zn(OH)4].\n**Шаг 4.** **Фиксируем порядок ответа:** X = 4, Y = 2 → в бланк записываем **42**."}, "06.13": {"t": "Модуль 06 · Задача 2. Две пробирки с раствором карбоната натрия (Na2CO3)", "x": "**Условие:** В две пробирки с раствором Na2CO3 добавили раствор вещества X (в первой выпал белый осадок, газ не выделялся) и раствор вещества Y (во второй выпал белый осадок и выделился газ без запаха). Список: *(1) HCl, (2) Ba(NO3)2, (3) AlCl3, (4) K2SO4, (5) NaOH*."}, "06.16": {"t": "Модуль 06 · Задача 3. Реакция без видимых признаков vs выпадение осадка", "x": "**Условие:** В две пробирки с раствором гидроксида калия KOH добавили раствор соли X (выпал голубой осадок) и раствор вещества Y (произошла реакция без видимых признаков). Список: *(1) CuSO4, (2) FeCl3, (3) Na2SO4, (4) KHCO3, (5) Ba(NO3)2*."}, "06.18": {"t": "Модуль 06 · Ловушка ЕГЭ: «растворение» BaCO3 в серной кислоте", "x": "В задании № 6 часто дают **осадок BaCO3** и просят растворить его. Если в списке есть H2SO4 и HCl, выбирай **HCl**, а не H2SO4! При действии H2SO4 на BaCO3 образуется нерастворимый BaSO4↓ — один осадок просто сменится другим (полного растворения осадка не произойдёт)."}, "07": {"t": "Модуль 07. Гидролиз солей: 4 типа и механизм смещения среды", "x": "**[[Гидролиз солей]]** — это обменное взаимодействие ионов соли с водой, приводящее к образованию слабого электролита и изменению среды раствора. Гидролиз всегда идёт **по слабому иону**, а среду раствора определяет **сильный ион**."}, "07.1": {"t": "Модуль 07 · Главная мысль.", "x": "**[[Гидролиз солей]]** — это обменное взаимодействие ионов соли с водой, приводящее к образованию слабого электролита и изменению среды раствора. Гидролиз всегда идёт **по слабому иону**, а среду раствора определяет **сильный ион**."}, "07.6": {"t": "Модуль 07 · 1. Механизм гидролиза: кто «перетягивает» ионы воды", "x": "Сводная матрица 4 типов солей: тип гидролиза определяется слабым ионом, а среда — избытком H⁺ или OH⁻."}, "07.10": {"t": "Модуль 07 · 2. Как писать уравнения гидролиза по 1-й ступени", "x": "По катиону (1-я ступень):  Al^{3+} + H2O ⇄ AlOH^{2+} + H^{+}\nМолекулярное:              AlCl3 + H2O ⇄ AlOHCl2 + HCl   (среда кислая, pH < 7)"}, "07.11": {"t": "Модуль 07 · 2. Как писать уравнения гидролиза по 1-й ступени", "x": "По аниону (1-я ступень):   CO3^{2−} + H2O ⇄ HCO3^{−} + OH^{−}\nМолекулярное:              Na2CO3 + H2O ⇄ NaHCO3 + NaOH  (среда щелочная, pH > 7)"}, "07.12": {"t": "Модуль 07 · 2. Как писать уравнения гидролиза по 1-й ступени", "x": "По катиону (NH4^{+}):      NH4^{+} + H2O ⇄ NH3·H2O + H^{+}\nПо аниону (CH3COO^{−}):    CH3COO^{−} + H2O ⇄ CH3COOH + OH^{−}"}, "07.14": {"t": "Модуль 07 · 3. Соли 4-го типа (слабое + слабая) и нерастворимые соли", "x": "• **Обратимый гидролиз по катиону и аниону:** если соль образована слабым основанием и слабой кислотой, но существует в растворе (классический пример ЕГЭ — ацетат аммония CH3COONH4), гидролиз идёт одновременно по обоим ионам: ионное CH3COO^{−} + NH4^{+} + H2O ⇄ CH3COOH + NH3·H2O, молекулярное CH3COONH4 + H2O ⇄ CH3COOH + NH3·H2O. Поскольку NH3·H2O и CH3COOH имеют почти одинаковую силу (K_b ≈ K_a ≈ 1,8·10⁻⁵), количества образующихся H^{+} и OH^{−} равны, и среда раствора CH3COONH4 **нейтральная (pH ≈ 7)**. А у (NH4)2CO3 или (NH4)2S кислота слабее аммиака, поэтому среда слабощелочная.\n• **Необратимый гидролиз (прочерк «–» в таблице ФИПИ):** сухие соли вроде Al2S3, Cr2S3, Al2(CO3)3 при попадании в воду разлагаются **необратимо до конца** на гидроксид и газ (Al2S3 + 6H2O → 2Al(OH)3↓ + 3H2S↑). Именно это мы использовали в совместном гидролизе в модуле 05.…"}, "07.17": {"t": "Модуль 07 · 4. Как усилить или подавить обратимый гидролиз (связь с № 22)", "x": "• ****Нагревание**** — Как меняется гидролиз: **Усиливается**; Почему: Гидролиз — процесс, обратный нейтрализации, поэтому он эндотермичен (−Q): нагрев смещает равновесие вправо.\n• ****Разбавление водой**** — Как меняется гидролиз: **Усиливается** (степень гидролиза растёт); Почему: Добавляем реагент (H2O), равновесие сдвигается в сторону продуктов гидролиза.\n• ****Добавление сильной кислоты (H^{+})**** — Как меняется гидролиз: По катиону **подавляется**; по аниону **усиливается**; Почему: Избыток H^{+} смещает равновесие Kt^{+} + H2O ⇄ KtOH + H^{+} влево, а в An^{−} + H2O ⇄ HAn + OH^{−} связывает OH^{−} в воду и тянет вправо.\n• ****Добавление щёлочи (OH^{−})**** — Как меняется гидролиз: По аниону **подавляется**; по катиону **усиливается**; Почему: Избыток OH^{−} подавляет гидролиз по аниону и связывает H^{+} при гидролизе по катиону."}, "07.18": {"t": "Модуль 07 · Ловушка ЕГЭ: «сильные» анионы и ловушка магния Mg²⁺", "x": "Две классические ловушки с «сильными» ионами: (1) кислородсодержащие анионы SO4^{2−}, NO3^{−}, ClO4^{−}, ClO3^{−}, MnO4^{−} относятся к **сильным** кислотам, поэтому Na2SO4, KNO3, BaCl2 и NaClO4 **не гидролизуются** (pH = 7); (2) **ловушка магния (Mg^{2+}):** хотя магний стоит во IIА группе, Mg(OH)2 — нерастворимое **слабое** основание, а не щёлочь! Поэтому соли MgCl2, Mg(NO3)2, MgSO4 гидролизуются по катиону и дают **кислую среду (pH < 7)**, в отличие от солей Ca^{2+}, Sr^{2+}, Ba^{2+} (pH = 7)."}, "08": {"t": "Модуль 08. Ионное произведение воды, шкала pH и кислые соли в № 21", "x": "При 25 °C произведение концентраций [H^{+}]·[OH^{−}] в любом водном растворе постоянно и равно 10⁻¹⁴ (**[[ионное произведение воды]] Kw**). Показатель **[[водородный показатель|pH]]** измеряет кислотность на логарифмической шкале от 0 до 14: чем выше концентрация H^{+}, тем **меньше** pH."}, "08.1": {"t": "Модуль 08 · Главная мысль.", "x": "При 25 °C произведение концентраций [H^{+}]·[OH^{−}] в любом водном растворе постоянно и равно 10⁻¹⁴ (**[[ионное произведение воды]] Kw**). Показатель **[[водородный показатель|pH]]** измеряет кислотность на логарифмической шкале от 0 до 14: чем выше концентрация H^{+}, тем **меньше** pH."}, "08.4": {"t": "Модуль 08 · 1. Ионное произведение воды Kw и физический смысл pH", "x": "Kw = [H^{+}] · [OH^{−}] = 10⁻¹⁴   (при 25 °C)"}, "08.7": {"t": "Модуль 08 · 1. Ионное произведение воды Kw и физический смысл pH", "x": "• **Кислая среда:** [H^{+}] > 10⁻⁷ моль/л → **pH < 7** (например, [H^{+}] = 10⁻² → pH = 2).\n• **Нейтральная среда:** [H^{+}] = [OH^{−}] = 10⁻⁷ моль/л → **pH = 7**.\n• **Щелочная среда:** [H^{+}] < 10⁻⁷ моль/л ([OH^{−}] > 10⁻⁷) → **pH > 7** (например, [H^{+}] = 10⁻¹² → pH = 12).\n• **Логарифмический шаг:** уменьшение pH на 1 единицу означает рост концентрации H^{+} в **10 раз**, а на 2 единицы — в **100 раз**."}, "08.8": {"t": "Модуль 08 · 1. Ионное произведение воды Kw и физический смысл pH", "x": "Карта зон pH (при одинаковой молярной концентрации растворов) и переходы окраски трёх экзаменационных индикаторов."}, "08.10": {"t": "Модуль 08 · 2. Индикаторы: как визуально определяют среду", "x": "• ****Лакмус**** — Кислая среда (pH < 7): Красный; Нейтральная среда (pH = 7): Фиолетовый; Щелочная среда (pH > 7): Синий\n• ****Метилоранж**** — Кислая среда (pH < 7): Красный (розовый); Нейтральная среда (pH = 7): Оранжевый; Щелочная среда (pH > 7): Жёлтый\n• ****Фенолфталеин (ФФ)**** — Кислая среда (pH < 7): Бесцветный; Нейтральная среда (pH = 7): Бесцветный; Щелочная среда (pH > 7): Малиновый"}, "08.16": {"t": "Модуль 08 · Среда кислых солей щелочных металлов (Na⁺, K⁺) в № 21", "x": "• **Кислая среда (pH < 7): диссоциация > гидролиза**: **NaHSO4, KHSO4** — **сильнокислая** среда (HSO4^{−} практически не гидролизуется, а активно отдаёт H^{+}). Стоит рядом с сильными/слабыми кислотами.; **NaH2PO4, KH2PO4** — **слабокислая** среда (H2PO4^{−} ⇄ H^{+} + HPO4^{2−} преобладает над гидролизом).; **NaHSO3, KHSO3** — **слабокислая** среда (HSO3^{−} ⇄ H^{+} + SO3^{2−} преобладает над гидролизом).\n• **Щелочная среда (pH > 7): гидролиз > диссоциации**: **NaHCO3, KHCO3** — **слабощелочная** среда (HCO3^{−} + H2O ⇄ H2CO3 + OH^{−} преобладает; пищевая сода слегка щелочная!).; **Na2HPO4, K2HPO4** — **слабощелочная** среда (HPO4^{2−} + H2O ⇄ H2PO4^{−} + OH^{−} преобладает).; **NaHS, KHS** — **слабощелочная** среда (HS^{−} + H2O ⇄ H2S + OH^{−} преобладает)."}, "09": {"t": "Модуль 09. Задание № 21 без ошибок: ранжирование растворов по pH", "x": "В задании № 21 тебе нужно расположить 4 водных раствора **одинаковой молярной концентрации** в порядке **возрастания** или **убывания** pH. Секрет 100% точности — сначала приписать каждому веществу «этаж» на шкале pH, затем развести соседей внутри одного этажа и в конце **дважды** проверить направление стрелки (возрастание vs убывание)."}, "09.1": {"t": "Модуль 09 · Главная мысль.", "x": "В задании № 21 тебе нужно расположить 4 водных раствора **одинаковой молярной концентрации** в порядке **возрастания** или **убывания** pH. Секрет 100% точности — сначала приписать каждому веществу «этаж» на шкале pH, затем развести соседей внутри одного этажа и в конце **дважды** проверить направление стрелки (возрастание vs убывание)."}, "09.4": {"t": "Модуль 09 · 1. Органические вещества и неэлектролиты в задании № 21", "x": "• ****Карбоновые кислоты**** — Примеры из КИМ: HCOOH, CH3COOH, C2H5COOH; Среда и зона pH: **Слабокислая (pH < 7)**; pH(HCOOH) < pH(CH3COOH); Почему так: Слабые электролиты, диссоциируют с отщеплением H^{+} (муравьиная сильнее уксусной).\n• ****Фенолы**** — Примеры из КИМ: C6H5OH (фенол); Среда и зона pH: **Очень слабокислая (pH < 7)**, но выше, чем у CH3COOH; Почему так: Фенол — ещё более слабая кислота, чем угольная и уксусная.\n• ****Спирты, углеводы, нейтральные аминокислоты**** — Примеры из КИМ: CH3OH, C2H5OH, глицерин, глюкоза, глицин (NH2CH2COOH); Среда и зона pH: **Нейтральная (pH ≈ 7)**; Почему так: Спирты и глюкоза — неэлектролиты; у глицина одна -NH2 и одна -COOH взаимно компенсируют друг друга.…"}, "09.9": {"t": "Модуль 09 · Задача 1. Базовый микс с гидролизом (возрастание pH)", "x": "**Условие:** Расположите в порядке **возрастания** pH водные растворы одинаковой молярной концентрации: *(1) Na2SO4, (2) Al(NO3)3, (3) HNO3, (4) K2CO3*."}, "09.12": {"t": "Модуль 09 · Задача 2. Две сильные кислоты и две щёлочи (убывание pH)", "x": "**Условие:** Расположите в порядке **убывания** pH растворы одинаковой молярной концентрации: *(1) HCl, (2) Ba(OH)2, (3) H2SO4, (4) KOH*."}, "09.15": {"t": "Модуль 09 · Задача 3. Ряд фосфатов (кислые соли разных ступеней, возрастание pH)", "x": "**Условие:** Расположите в порядке **возрастания** pH растворы: *(1) Na2HPO4, (2) H3PO4, (3) Na3PO4, (4) NaH2PO4*."}, "09.18": {"t": "Модуль 09 · Задача 4. Конкуренция кислых солей и карбонатов (возрастание pH)", "x": "**Условие:** Расположите в порядке **возрастания** pH растворы: *(1) NaHCO3, (2) NaHSO4, (3) Na2CO3, (4) NH4Cl*."}, "09.21": {"t": "Модуль 09 · Задача 5. Органика в № 21 (убывание pH)", "x": "**Условие:** Расположите в порядке **убывания** pH водные растворы одинаковой молярной концентрации: *(1) CH3COOH, (2) C2H5OH, (3) CH3COONa, (4) KOH*."}, "09.24": {"t": "Модуль 09 · Мост к КИМ (№ 21 КИМ)", "x": "**Как спрашивают:** За № 21 ставят ровно 1 балл, и он засчитывается только при 100% совпадении всех четырёх цифр.\n**На чём ловят:** Внимательно читай названия солей: сульфат (SO4^{2−}, pH = 7) vs сульфит (SO3^{2−}, pH > 7) vs сульфид (S^{2−}, сильнощелочная); нитрат (NO3^{−}, pH = 7) vs нитрит (NO2^{−}, pH > 7); дигидрофосфат (pH < 7) vs гидрофосфат (pH > 7).\n**Как читать:** Всегда переводи русские названия из условия в химические формулы, подписывай над каждой формулой приблизительный pH (например, 1, 5, 7, 11) и только потом собирай цифры в нужном порядке."}}, "_kt": "Электролиты, РИО (№ 6, 30) и гидролиз/pH (№ 21)", "_mods": {"01": "Электролитическая диссоциация: почему растворы проводят ток", "02": "Таблица растворимости ФИПИ и анатомия ионных уравнений", "03": "Условия протекания РИО: осадок, газ, слабый электролит", "04": "Кислые соли в РИО: избыток/недостаток и дилемма `HSO4⁻`", "05": "Совместный гидролиз и границы РИО в задании № 30", "06": "Пробирки X и Y: качественные признаки РИО в задании № 6", "07": "Гидролиз солей: 4 типа и механизм смещения среды", "08": "Ионное произведение воды, шкала pH и кислые соли в № 21", "09": "Задание № 21 без ошибок: ранжирование растворов по pH"}, "_skm": {"electrolytes": ["01"], "fipi_solubility_piu": ["02"], "rio_conditions": ["03"], "acid_salts_rio": ["04"], "joint_hydrolysis_30": ["05"], "kim6_tubes": ["06"], "hydrolysis_4types": ["07"], "ph_scale_acid_salts": ["08"], "kim21_ranking": ["09"]}, "_fig": []};
